static SYSTEM_FONTS: OnceLock<Arc<usvg::fontdb::Database>> = OnceLock::new();
static PDF_FONTS: OnceLock<Arc<svg2pdf::usvg::fontdb::Database>> = OnceLock::new();
// Parsed SVG text is expensive for large CJK fonts. Key by all parser inputs so
// raw edits and embedded-font replacements cannot reuse a stale render tree.
type RenderTreeCache = VecDeque<([u8; 32], Arc<usvg::Tree>)>;
static RENDER_TREES: OnceLock<Mutex<RenderTreeCache>> = OnceLock::new();
const RENDER_TREE_CACHE_ENTRIES: usize = 4;
const RENDER_TREE_CACHE_INPUT_BYTES: usize = 8 * 1024 * 1024;
const RENDER_TREE_CACHE_PIXELS: u64 = 8_000_000;

fn render_tree_key(svg: &str, dpi: f32, embedded_fonts: &[&[u8]]) -> [u8; 32] {
    let mut hash = Sha256::new();
    hash.update(dpi.to_bits().to_le_bytes());
    hash.update((svg.len() as u64).to_le_bytes());
    hash.update(svg.as_bytes());
    for font in embedded_fonts {
        hash.update((font.len() as u64).to_le_bytes());
        hash.update(font);
    }
    hash.finalize().into()
}

fn cached_render_tree(key: [u8; 32]) -> Option<Arc<usvg::Tree>> {
    let mut trees = RENDER_TREES.get_or_init(Default::default).lock().ok()?;
    let index = trees.iter().position(|(candidate, _)| *candidate == key)?;
    let entry = trees.remove(index)?;
    let tree = Arc::clone(&entry.1);
    trees.push_back(entry);
    Some(tree)
}

fn cache_render_tree(key: [u8; 32], tree: Arc<usvg::Tree>) {
    if let Ok(mut trees) = RENDER_TREES.get_or_init(Default::default).lock() {
        if let Some(index) = trees.iter().position(|(candidate, _)| *candidate == key) {
            trees.remove(index);
        }
        trees.push_back((key, tree));
        while trees.len() > RENDER_TREE_CACHE_ENTRIES {
            trees.pop_front();
        }
    }
}

fn preferred_font_family(families: &[String]) -> Option<String> {
    let preferred = [
        "Noto Sans CJK SC",
        "Noto Serif CJK SC",
        "SimSun",
        "Microsoft YaHei",
        "DejaVu Sans",
        "Arial",
        "Liberation Sans",
    ];
    preferred
        .iter()
        .find(|name| families.iter().any(|family| family == **name))
        .map(|name| (*name).to_owned())
        .or_else(|| families.first().cloned())
}

fn system_fonts() -> Arc<usvg::fontdb::Database> {
    Arc::clone(SYSTEM_FONTS.get_or_init(|| {
        let mut database = usvg::fontdb::Database::new();
        database.load_system_fonts();
        set_fallback_font_family(&mut database);
        Arc::new(database)
    }))
}

fn set_fallback_font_family(fontdb: &mut usvg::fontdb::Database) {
    let families: Vec<_> = fontdb
        .faces()
        .flat_map(|face| face.families.iter().map(|(name, _)| name.clone()))
        .collect();
    if let Some(fallback) = preferred_font_family(&families) {
        fontdb.set_serif_family(fallback.clone());
        fontdb.set_sans_serif_family(fallback.clone());
        fontdb.set_monospace_family(fallback);
    }
}

fn pdf_system_fonts() -> Arc<svg2pdf::usvg::fontdb::Database> {
    Arc::clone(PDF_FONTS.get_or_init(|| {
        let mut database = svg2pdf::usvg::fontdb::Database::new();
        database.load_system_fonts();
        let families: Vec<_> = database
            .faces()
            .flat_map(|face| face.families.iter().map(|(name, _)| name.clone()))
            .collect();
        if let Some(fallback) = preferred_font_family(&families) {
            database.set_serif_family(fallback.clone());
            database.set_sans_serif_family(fallback.clone());
            database.set_monospace_family(fallback);
        }
        Arc::new(database)
    }))
}

/// Errors raised when parsing or writing an OFD package.
#[derive(Debug, Error)]
pub enum OfdError {
    /// The underlying file or stream failed.
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    /// The ZIP container is invalid.
    #[error("ZIP error: {0}")]
    Zip(#[from] zip::result::ZipError),
    /// An XML file could not be parsed.
    #[error("invalid XML in {path}: {message}")]
    Xml { path: String, message: String },
    /// A required OFD element or resource is missing.
    #[error("invalid OFD: {0}")]
    Invalid(String),
    /// An archive entry path would escape the package or is otherwise unsafe.
    #[error("invalid package path: {0}")]
    InvalidPath(String),
    /// An archive exceeds the configured resource limit.
    #[error("OFD package exceeds resource limit: {0}")]
    Limit(String),
    /// The requested page index is out of bounds.
    #[error("page index {index} is out of bounds for {count} pages")]
    PageIndex { index: usize, count: usize },
}

/// Physical page geometry and the location of its XML content.
#[derive(Debug, Clone, PartialEq)]
pub struct PageInfo {
    /// The zero-based page index in document order.
    pub index: usize,
    /// The zero-based index of the containing document.
    pub document_index: usize,
    /// The OFD page identifier.
    pub id: String,
    /// Normalized package path of the page XML.
    pub path: String,
    /// Effective page canvas in millimeters. If `PhysicalBox` is absent, the
    /// selected area's `ApplicationBox` or `ContentBox` supplies the canvas.
    pub physical_box: Option<[f64; 4]>,
    /// Effective visible or printable area, when specified.
    pub application_box: Option<[f64; 4]>,
    /// Effective body text area, when specified.
    pub content_box: Option<[f64; 4]>,
    /// Effective bleed area; defaults to the physical page box.
    pub bleed_box: Option<[f64; 4]>,
}

