#[derive(Debug, Clone, PartialEq)]
pub struct StrokeStyleInfo {
    pub line_width: f64,
    /// Path-only SVG cap name: `butt`, `round`, or `square`.
    pub cap: Option<String>,
    /// Path-only SVG join name: `miter`, `round`, or `bevel`.
    pub join: Option<String>,
    pub miter_limit: Option<f64>,
    pub dash_pattern: Option<[f64; 2]>,
    /// Full OFD dash sequence; `dash_pattern` remains available for two-value patterns.
    pub dash_sequence: Option<Vec<f64>>,
    /// Zero when no dash pattern is selected.
    pub dash_offset: f64,
}

/// Direct stroke geometry to write on an existing path object.
/// Optional values clear the corresponding object attribute, allowing a
/// DrawParam or OFD default to supply it. `line_width` is always written.
#[derive(Debug, Clone, PartialEq)]
pub struct PathStrokeStyle {
    pub line_width: f64,
    pub cap: Option<PathLineCap>,
    pub join: Option<PathLineJoin>,
    pub miter_limit: Option<f64>,
    pub dash_pattern: Option<[f64; 2]>,
    pub dash_sequence: Option<Vec<f64>>,
    pub dash_offset: Option<f64>,
}

impl Default for PathStrokeStyle {
    fn default() -> Self {
        Self {
            line_width: 0.4,
            cap: None,
            join: None,
            miter_limit: None,
            dash_pattern: None,
            dash_sequence: None,
            dash_offset: None,
        }
    }
}

impl PathStrokeStyle {
    fn validate(&self) -> Result<(), OfdError> {
        if self.dash_pattern.is_some() && self.dash_sequence.is_some() {
            return Err(OfdError::Invalid("path has two dash definitions".into()));
        }
        if !self.line_width.is_finite()
            || self.line_width <= 0.0
            || self
                .miter_limit
                .is_some_and(|value| !value.is_finite() || value <= 0.0)
            || self.dash_pattern.is_some_and(|values| {
                values
                    .iter()
                    .any(|value| !value.is_finite() || *value <= 0.0)
            })
            || self.dash_sequence.as_ref().is_some_and(|values| {
                values.is_empty()
                    || values.len() > 256
                    || values
                        .iter()
                        .any(|value| !value.is_finite() || *value <= 0.0)
            })
            || self.dash_offset.is_some_and(|value| !value.is_finite())
        {
            return Err(OfdError::Invalid("path stroke style is invalid".into()));
        }
        Ok(())
    }

    fn attributes(&self) -> [(&'static str, Option<String>); 6] {
        [
            ("LineWidth", Some(self.line_width.to_string())),
            ("Cap", self.cap.map(|value| value.ofd_name().to_owned())),
            ("Join", self.join.map(|value| value.ofd_name().to_owned())),
            (
                "MiterLimit",
                self.miter_limit.map(|value| value.to_string()),
            ),
            (
                "DashPattern",
                self.dash_pattern
                    .map(|[dash, gap]| format!("{dash} {gap}"))
                    .or_else(|| {
                        self.dash_sequence.as_ref().map(|values| {
                            values
                                .iter()
                                .map(f64::to_string)
                                .collect::<Vec<_>>()
                                .join(" ")
                        })
                    }),
            ),
            (
                "DashOffset",
                self.dash_offset.map(|value| value.to_string()),
            ),
        ]
    }
}

