/// Optional attributes of an OFD Sound action.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SoundActionOptions {
    pub volume: Option<u8>,
    pub repeat: Option<bool>,
    pub synchronous: Option<bool>,
}

impl SoundActionOptions {
    fn validate(self) -> Result<(), OfdError> {
        if self.volume.is_some_and(|value| value > 100) {
            return Err(OfdError::Invalid(
                "Sound volume must be between 0 and 100".into(),
            ));
        }
        Ok(())
    }
}

