#[derive(Clone)]
enum PdfLinkTarget {
    Uri(String),
    Goto(DestinationInfo),
    Attachment(Ref),
}

fn pdf_link_target(
    action: &PageObjectActionInfo,
    document_index: usize,
    pages: &[PageInfo],
    bookmarks: &[BookmarkInfo],
    attachments: &HashMap<(usize, String), Ref>,
) -> Option<PdfLinkTarget> {
    if action.event != "CLICK" {
        return None;
    }
    match action.kind.as_str() {
        "URI" => action
            .attributes
            .get("URI")
            .filter(|uri| !uri.is_empty())
            .map(|uri| PdfLinkTarget::Uri(uri.clone())),
        "Goto" => {
            let destination = action.destination.clone().or_else(|| {
                action.bookmark.as_ref().and_then(|name| {
                    bookmarks
                        .iter()
                        .find(|bookmark| {
                            bookmark.document_index == document_index && bookmark.name == *name
                        })
                        .map(|bookmark| bookmark.destination.clone())
                })
            })?;
            if !matches!(
                destination.kind.as_str(),
                "XYZ" | "Fit" | "FitH" | "FitV" | "FitR"
            ) || resolve_page_id(pages, document_index, &destination.page_id).is_err()
            {
                return None;
            }
            Some(PdfLinkTarget::Goto(destination))
        }
        "GotoA" => action
            .attributes
            .get("AttachID")
            .and_then(|id| attachments.get(&(document_index, id.clone())))
            .copied()
            .map(PdfLinkTarget::Attachment),
        _ => None,
    }
}

fn civil_date_from_unix_days(days: i64) -> (i64, u32, u32) {
    let days = days + 719_468;
    let era = if days >= 0 { days } else { days - 146_096 } / 146_097;
    let day_of_era = days - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let mut year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_prime = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    if month <= 2 {
        year += 1;
    }
    (year, month as u32, day as u32)
}

fn current_utc_date() -> Result<String, OfdError> {
    let seconds = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| OfdError::Invalid("system clock predates Unix epoch".into()))?
        .as_secs();
    let (year, month, day) = civil_date_from_unix_days((seconds / 86_400) as i64);
    Ok(format!("{year:04}-{month:02}-{day:02}"))
}

fn pdf_date_from_ofd(value: &str) -> Option<Date> {
    let bytes = value.as_bytes();
    if bytes.len() != 10
        || bytes[4] != b'-'
        || bytes[7] != b'-'
        || !bytes[..4]
            .iter()
            .chain(&bytes[5..7])
            .chain(&bytes[8..])
            .all(u8::is_ascii_digit)
    {
        return None;
    }
    let year = value[..4].parse::<u16>().ok()?;
    let month = value[5..7].parse::<u8>().ok()?;
    let day = value[8..].parse::<u8>().ok()?;
    pdf_import::calendar_day_valid(year, month, day).then(|| Date::new(year).month(month).day(day))
}

fn valid_ofd_datetime(value: &str) -> bool {
    let bytes = value.as_bytes();
    if bytes.len() != 19
        || !bytes[..10].is_ascii()
        || bytes[10] != b'T'
        || bytes[13] != b':'
        || bytes[16] != b':'
        || !bytes[11..13]
            .iter()
            .chain(&bytes[14..16])
            .chain(&bytes[17..19])
            .all(u8::is_ascii_digit)
        || pdf_date_from_ofd(&value[..10]).is_none()
    {
        return false;
    }
    let hour = value[11..13].parse::<u8>().unwrap_or(255);
    let minute = value[14..16].parse::<u8>().unwrap_or(255);
    let second = value[17..19].parse::<u8>().unwrap_or(255);
    hour < 24 && minute < 60 && second < 60
}

fn pdf_attachment_datetime_from_ofd(value: &str) -> Option<Date> {
    if !valid_ofd_datetime(value) {
        return None;
    }
    Some(
        pdf_date_from_ofd(&value[..10])?
            .hour(value[11..13].parse().ok()?)
            .minute(value[14..16].parse().ok()?)
            .second(value[17..19].parse().ok()?),
    )
}

fn pdf_attachment_usage(usage: &str) -> Option<&str> {
    (usage != "none"
        && !usage.is_empty()
        && usage.is_ascii()
        && usage.bytes().all(|byte| (b'!'..=b'~').contains(&byte)))
    .then_some(usage)
}

fn write_pdf_destination(
    writer: pdf_writer::writers::Destination<'_>,
    destination: &DestinationInfo,
    target: &PageInfo,
    target_ref: Ref,
) -> Result<(), OfdError> {
    let [tx, ty, _, th] = target
        .physical_box
        .ok_or_else(|| OfdError::Invalid(format!("page {} has no physical box", target.id)))?;
    let point = |value: f64| -> Result<f32, OfdError> {
        let points = value * 72.0 / 25.4;
        if !points.is_finite() || points.abs() > f32::MAX as f64 {
            return Err(OfdError::Limit(
                "PDF destination coordinates exceed supported range".into(),
            ));
        }
        Ok(points as f32)
    };
    let writer = writer.page(target_ref);
    match destination.kind.as_str() {
        "XYZ" => writer.xyz(
            point(destination.left.unwrap_or(tx) - tx)?,
            point(ty + th - destination.top.unwrap_or(ty))?,
            destination.zoom.map(|zoom| zoom as f32),
        ),
        "FitH" => writer.fit_horizontal(point(ty + th - destination.top.unwrap_or(ty))?),
        "FitV" => writer.fit_vertical(point(destination.left.unwrap_or(tx) - tx)?),
        "FitR" => writer.fit_rect(Rect::new(
            point(destination.left.unwrap_or(tx) - tx)?,
            point(ty + th - destination.bottom.unwrap_or(ty + th))?,
            point(destination.right.unwrap_or(tx) - tx)?,
            point(ty + th - destination.top.unwrap_or(ty))?,
        )),
        "Fit" => writer.fit(),
        _ => {
            return Err(OfdError::Invalid(format!(
                "unsupported PDF destination kind: {}",
                destination.kind
            )))
        }
    }
    Ok(())
}

fn pdf_link_rect(boundary: [f64; 4], physical_box: [f64; 4]) -> Result<[f64; 4], OfdError> {
    let [x, y, width, height] = boundary;
    if !boundary.iter().all(|value| value.is_finite()) || width <= 0.0 || height <= 0.0 {
        return Err(OfdError::Invalid("link boundary is invalid".into()));
    }
    let [page_x, page_y, _, page_height] = physical_box;
    let scale = 72.0 / 25.4;
    let rect = [
        (x - page_x) * scale,
        (page_y + page_height - y - height) * scale,
        (x - page_x + width) * scale,
        (page_y + page_height - y) * scale,
    ];
    if rect
        .iter()
        .any(|value| !value.is_finite() || value.abs() > f32::MAX as f64)
    {
        return Err(OfdError::Limit(
            "PDF link coordinates exceed supported range".into(),
        ));
    }
    Ok(rect)
}

struct PdfLinkShape {
    boundary: [f64; 4],
    quad: Option<[[f64; 2]; 4]>,
}

struct PdfLinkOutputRegion {
    rect: [f64; 4],
    quads: Option<Vec<f32>>,
}

pub(crate) fn convex_quad_turn(points: [[f64; 2]; 4]) -> Option<f64> {
    if points.iter().flatten().any(|value| !value.is_finite()) {
        return None;
    }
    let cross = |a: [f64; 2], b: [f64; 2], c: [f64; 2]| {
        (b[0] - a[0]) * (c[1] - b[1]) - (b[1] - a[1]) * (c[0] - b[0])
    };
    let first = cross(points[0], points[1], points[2]);
    if !first.is_finite() || first.abs() <= 1e-12 {
        return None;
    }
    (1..4)
        .all(|index| {
            let turn = cross(
                points[index],
                points[(index + 1) % 4],
                points[(index + 2) % 4],
            );
            turn.is_finite() && turn.abs() > 1e-12 && turn.signum() == first.signum()
        })
        .then_some(first)
}

fn pdf_link_quad(points: [[f64; 2]; 4], physical_box: [f64; 4]) -> Result<[f32; 8], OfdError> {
    let [page_x, page_y, _, page_height] = physical_box;
    let scale = 72.0 / 25.4;
    let mut output = [0.0; 8];
    for (index, [x, y]) in points.into_iter().enumerate() {
        let pdf_x = (x - page_x) * scale;
        let pdf_y = (page_y + page_height - y) * scale;
        if !pdf_x.is_finite()
            || !pdf_y.is_finite()
            || pdf_x.abs() > f32::MAX as f64
            || pdf_y.abs() > f32::MAX as f64
        {
            return Err(OfdError::Limit(
                "PDF link coordinates exceed supported range".into(),
            ));
        }
        output[index * 2] = pdf_x as f32;
        output[index * 2 + 1] = pdf_y as f32;
    }
    Ok(output)
}

struct PdfTextMarkupData {
    kind: AnnotationType,
    quads: Vec<f32>,
    color: [u8; 3],
    opacity: u8,
}

struct PdfTextNoteData {
    icon: &'static [u8],
    open: bool,
    color: Option<[u8; 3]>,
    opacity: Option<u8>,
}

struct PdfShapeData {
    kind: PdfShapeKind,
    line: Option<[f64; 4]>,
    ink: Option<Vec<Vec<f64>>>,
    vertices: Option<Vec<f64>>,
    intent: Option<&'static str>,
    line_endings: Option<[&'static str; 2]>,
    line_leader: Option<[f64; 3]>,
    stroke: Option<[u8; 3]>,
    fill: Option<[u8; 3]>,
    width: f64,
    dash: Option<Vec<f64>>,
    opacity: u8,
    insets: [f64; 4],
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum PdfShapeKind {
    Square,
    Circle,
    Line,
    Ink,
    Polygon,
    PolyLine,
}

fn pdf_poly_path(
    vertices: &[f64],
    width: f64,
    height: f64,
    closed: bool,
) -> Result<String, OfdError> {
    let mut pairs = vertices.chunks_exact(2);
    let first = pairs
        .next()
        .ok_or_else(|| OfdError::Invalid("PDF polygon has no vertices".into()))?;
    let mut path = format!("M {} {}", first[0] * width, first[1] * height);
    for pair in pairs {
        path.push_str(&format!(" L {} {}", pair[0] * width, pair[1] * height));
    }
    if closed {
        path.push_str(" C");
    }
    Ok(path)
}

fn pdf_ink_path(points: &[f64], width: f64, height: f64) -> Result<String, OfdError> {
    let mut pairs = points.chunks_exact(2);
    let first = pairs
        .next()
        .ok_or_else(|| OfdError::Invalid("PDF Ink stroke has no points".into()))?;
    let mut path = format!("M {} {}", first[0] * width, first[1] * height);
    for pair in pairs {
        path.push_str(&format!(" L {} {}", pair[0] * width, pair[1] * height));
    }
    if points.len() == 2 {
        path.push_str(&format!(" L {} {}", first[0] * width, first[1] * height));
    }
    Ok(path)
}

fn pdf_line_ending_name(value: &str) -> Option<&'static str> {
    match value {
        "None" => Some("None"),
        "Square" => Some("Square"),
        "Circle" => Some("Circle"),
        "Diamond" => Some("Diamond"),
        "OpenArrow" => Some("OpenArrow"),
        "ClosedArrow" => Some("ClosedArrow"),
        "Butt" => Some("Butt"),
        "ROpenArrow" => Some("ROpenArrow"),
        "RClosedArrow" => Some("RClosedArrow"),
        "Slash" => Some("Slash"),
        _ => None,
    }
}

fn pdf_shape_data(annotation: &AnnotationInfo) -> Result<Option<PdfShapeData>, OfdError> {
    let Some(kind) = annotation.parameters.get("PDFShape") else {
        return Ok(None);
    };
    let kind = match (
        kind.as_str(),
        annotation.annotation_type.as_str(),
        annotation.subtype.as_deref(),
    ) {
        ("Square", "Square", _) | ("Square", "Path", Some("Square")) => PdfShapeKind::Square,
        ("Circle", "Circle", _) | ("Circle", "Path", Some("Circle")) => PdfShapeKind::Circle,
        ("Line", "Line", _) | ("Line", "Path", Some("Line")) => PdfShapeKind::Line,
        ("Ink", "Path", Some("Ink")) => PdfShapeKind::Ink,
        ("Polygon", "Path", Some("Polygon")) => PdfShapeKind::Polygon,
        ("PolyLine", "Path", Some("PolyLine")) => PdfShapeKind::PolyLine,
        _ => {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFShape",
                annotation.id
            )))
        }
    };
    let parse_color = |key: &str| -> Result<Option<[u8; 3]>, OfdError> {
        annotation
            .parameters
            .get(key)
            .map(|raw| {
                let values = raw
                    .split_whitespace()
                    .map(str::parse::<u8>)
                    .collect::<Result<Vec<_>, _>>()
                    .map_err(|_| {
                        OfdError::Invalid(format!("annotation {} has invalid {key}", annotation.id))
                    })?;
                values.try_into().map_err(|_| {
                    OfdError::Invalid(format!("annotation {} has invalid {key}", annotation.id))
                })
            })
            .transpose()
    };
    let width = annotation
        .parameters
        .get("PDFShapeWidth")
        .ok_or_else(|| {
            OfdError::Invalid(format!("annotation {} has no PDFShapeWidth", annotation.id))
        })?
        .parse::<f64>()
        .map_err(|_| {
            OfdError::Invalid(format!(
                "annotation {} has invalid PDFShapeWidth",
                annotation.id
            ))
        })?;
    if !width.is_finite() || !(0.0..=1e6).contains(&width) {
        return Err(OfdError::Invalid(format!(
            "annotation {} has invalid PDFShapeWidth",
            annotation.id
        )));
    }
    let opacity = annotation
        .parameters
        .get("PDFShapeOpacity")
        .ok_or_else(|| {
            OfdError::Invalid(format!(
                "annotation {} has no PDFShapeOpacity",
                annotation.id
            ))
        })?
        .parse::<u8>()
        .map_err(|_| {
            OfdError::Invalid(format!(
                "annotation {} has invalid PDFShapeOpacity",
                annotation.id
            ))
        })?;
    let dash = annotation
        .parameters
        .get("PDFShapeDash")
        .map(|raw| {
            let values = raw
                .split_whitespace()
                .map(str::parse::<f64>)
                .collect::<Result<Vec<_>, _>>()
                .map_err(|_| {
                    OfdError::Invalid(format!(
                        "annotation {} has invalid PDFShapeDash",
                        annotation.id
                    ))
                })?;
            if values.is_empty()
                || values.len() > 256
                || values
                    .iter()
                    .any(|value| !value.is_finite() || *value <= 0.0 || *value > 1e6)
            {
                return Err(OfdError::Invalid(format!(
                    "annotation {} has invalid PDFShapeDash",
                    annotation.id
                )));
            }
            Ok(values)
        })
        .transpose()?;
    let insets = annotation
        .parameters
        .get("PDFShapeInsets")
        .and_then(|raw| parse_numbers::<4>(raw))
        .ok_or_else(|| {
            OfdError::Invalid(format!(
                "annotation {} has invalid PDFShapeInsets",
                annotation.id
            ))
        })?;
    if insets
        .iter()
        .any(|value| !value.is_finite() || *value < -1e-6 || *value >= 1.0)
        || insets[0] + insets[2] >= 1.0
        || insets[1] + insets[3] >= 1.0
    {
        return Err(OfdError::Invalid(format!(
            "annotation {} has invalid PDFShapeInsets",
            annotation.id
        )));
    }
    let line = if kind == PdfShapeKind::Line {
        let line = annotation
            .parameters
            .get("PDFLine")
            .and_then(|raw| parse_numbers::<4>(raw))
            .ok_or_else(|| {
                OfdError::Invalid(format!("annotation {} has invalid PDFLine", annotation.id))
            })?;
        if line
            .iter()
            .any(|value| !value.is_finite() || !(0.0..=1.0).contains(value))
            || (line[0] == line[2] && line[1] == line[3])
        {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFLine",
                annotation.id
            )));
        }
        Some(line)
    } else {
        None
    };
    let line_endings = annotation
        .parameters
        .get("PDFLineEndings")
        .map(|raw| {
            let values = raw.split_whitespace().collect::<Vec<_>>();
            let [start, end] = values.as_slice() else {
                return Err(OfdError::Invalid(format!(
                    "annotation {} has invalid PDFLineEndings",
                    annotation.id
                )));
            };
            if !matches!(kind, PdfShapeKind::Line | PdfShapeKind::PolyLine) {
                return Err(OfdError::Invalid(format!(
                    "annotation {} has invalid PDFLineEndings",
                    annotation.id
                )));
            }
            Ok([
                pdf_line_ending_name(start).ok_or_else(|| {
                    OfdError::Invalid(format!(
                        "annotation {} has invalid PDFLineEndings",
                        annotation.id
                    ))
                })?,
                pdf_line_ending_name(end).ok_or_else(|| {
                    OfdError::Invalid(format!(
                        "annotation {} has invalid PDFLineEndings",
                        annotation.id
                    ))
                })?,
            ])
        })
        .transpose()?;
    let line_leader = annotation
        .parameters
        .get("PDFLineLeader")
        .map(|raw| {
            let values = parse_numbers::<3>(raw).ok_or_else(|| {
                OfdError::Invalid(format!(
                    "annotation {} has invalid PDFLineLeader",
                    annotation.id
                ))
            })?;
            if kind != PdfShapeKind::Line
                || values
                    .iter()
                    .any(|value| !value.is_finite() || value.abs() > 1e6)
                || values[1] < 0.0
                || values[2] < 0.0
            {
                return Err(OfdError::Invalid(format!(
                    "annotation {} has invalid PDFLineLeader",
                    annotation.id
                )));
            }
            Ok(values)
        })
        .transpose()?;
    let ink = if kind == PdfShapeKind::Ink {
        let raw = annotation.parameters.get("PDFInkList").ok_or_else(|| {
            OfdError::Invalid(format!("annotation {} has no PDFInkList", annotation.id))
        })?;
        let strokes = raw
            .split(';')
            .map(|stroke| {
                stroke
                    .split_whitespace()
                    .map(str::parse::<f64>)
                    .collect::<Result<Vec<_>, _>>()
            })
            .collect::<Result<Vec<_>, _>>()
            .map_err(|_| {
                OfdError::Invalid(format!(
                    "annotation {} has invalid PDFInkList",
                    annotation.id
                ))
            })?;
        if strokes.is_empty()
            || strokes.len() > 4096
            || strokes.iter().any(|points| {
                points.len() < 2
                    || points.len() % 2 != 0
                    || points.len() > 200_000
                    || points
                        .iter()
                        .any(|value| !value.is_finite() || !(0.0..=1.0).contains(value))
            })
        {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFInkList",
                annotation.id
            )));
        }
        Some(strokes)
    } else {
        None
    };
    let vertices = if matches!(kind, PdfShapeKind::Polygon | PdfShapeKind::PolyLine) {
        let raw = annotation
            .parameters
            .get("PDFShapeVertices")
            .ok_or_else(|| {
                OfdError::Invalid(format!(
                    "annotation {} has no PDFShapeVertices",
                    annotation.id
                ))
            })?;
        let values = raw
            .split_whitespace()
            .map(str::parse::<f64>)
            .collect::<Result<Vec<_>, _>>()
            .map_err(|_| {
                OfdError::Invalid(format!(
                    "annotation {} has invalid PDFShapeVertices",
                    annotation.id
                ))
            })?;
        let minimum = if kind == PdfShapeKind::Polygon { 6 } else { 4 };
        if values.len() < minimum
            || values.len() % 2 != 0
            || values.len() > 200_000
            || values
                .iter()
                .any(|value| !value.is_finite() || !(0.0..=1.0).contains(value))
        {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFShapeVertices",
                annotation.id
            )));
        }
        Some(values)
    } else {
        None
    };
    let intent = match annotation
        .parameters
        .get("PDFShapeIntent")
        .map(String::as_str)
    {
        None => None,
        Some("PolygonDimension") if kind == PdfShapeKind::Polygon => Some("PolygonDimension"),
        Some("PolyLineDimension") if kind == PdfShapeKind::PolyLine => Some("PolyLineDimension"),
        _ => {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFShapeIntent",
                annotation.id
            )))
        }
    };
    Ok(Some(PdfShapeData {
        kind,
        line,
        ink,
        vertices,
        intent,
        line_endings,
        line_leader,
        stroke: parse_color("PDFShapeStroke")?,
        fill: parse_color("PDFShapeFill")?,
        width,
        dash,
        opacity,
        insets,
    }))
}

fn pdf_shape_path(
    kind: &str,
    width: f64,
    height: f64,
    insets: [f64; 4],
) -> Result<String, OfdError> {
    if !width.is_finite() || !height.is_finite() || width <= 0.0 || height <= 0.0 {
        return Err(OfdError::Invalid("PDF shape boundary is invalid".into()));
    }
    let [left, top, right, bottom] = insets;
    if insets
        .iter()
        .any(|value| !value.is_finite() || *value < -1e-6)
        || left + right >= 1.0
        || top + bottom >= 1.0
    {
        return Err(OfdError::Invalid("PDF shape inset is invalid".into()));
    }
    let left = left.max(0.0) * width;
    let top = top.max(0.0) * height;
    let shape_width = width - left - right.max(0.0) * width;
    let shape_height = height - top - bottom.max(0.0) * height;
    match kind {
        "Square" => Ok(format!(
            "M {left} {top} L {} {top} L {} {} L {left} {} C",
            left + shape_width,
            left + shape_width,
            top + shape_height,
            top + shape_height
        )),
        "Circle" => {
            let x = left + shape_width / 2.0;
            let y = top + shape_height / 2.0;
            let rx = shape_width / 2.0;
            let ry = shape_height / 2.0;
            let k = 0.552_284_749_830_793_6;
            Ok(format!("M {} {y} B {} {} {} {} {x} {} B {} {} {} {} {} {y} B {} {} {} {} {x} {} B {} {} {} {} {} {y} C",
                x + rx, x + rx, y + k * ry, x + k * rx, y + ry, y + ry,
                x - k * rx, y + ry, x - rx, y + k * ry, x - rx,
                x - rx, y - k * ry, x - k * rx, y - ry, y - ry,
                x + k * rx, y - ry, x + rx, y - k * ry, x + rx))
        }
        _ => Err(OfdError::Invalid("PDF shape kind is invalid".into())),
    }
}

fn pdf_text_note_data(annotation: &AnnotationInfo) -> Result<Option<PdfTextNoteData>, OfdError> {
    let Some(icon) = annotation.parameters.get("PDFTextIcon") else {
        return Ok(None);
    };
    if annotation.annotation_type != "Text"
        && !(annotation.annotation_type == "Path" && annotation.subtype.as_deref() == Some("Text"))
    {
        return Err(OfdError::Invalid(format!(
            "annotation {} has unsupported PDF Text type",
            annotation.id
        )));
    }
    let icon = match icon.as_str() {
        "Note" => b"Note".as_slice(),
        "Comment" => b"Comment".as_slice(),
        "Help" => b"Help".as_slice(),
        "Insert" => b"Insert".as_slice(),
        "Key" => b"Key".as_slice(),
        "NewParagraph" => b"NewParagraph".as_slice(),
        "Paragraph" => b"Paragraph".as_slice(),
        _ => {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFTextIcon",
                annotation.id
            )))
        }
    };
    let open = match annotation.parameters.get("PDFTextOpen").map(String::as_str) {
        Some("true") => true,
        Some("false") => false,
        _ => {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFTextOpen",
                annotation.id
            )))
        }
    };
    let color = annotation
        .parameters
        .get("PDFTextColor")
        .map(|raw| {
            let values = raw
                .split_whitespace()
                .map(str::parse::<u8>)
                .collect::<Result<Vec<_>, _>>()
                .map_err(|_| {
                    OfdError::Invalid(format!(
                        "annotation {} has invalid PDFTextColor",
                        annotation.id
                    ))
                })?;
            values.try_into().map_err(|_| {
                OfdError::Invalid(format!(
                    "annotation {} has invalid PDFTextColor",
                    annotation.id
                ))
            })
        })
        .transpose()?;
    let opacity = annotation
        .parameters
        .get("PDFTextOpacity")
        .map(|raw| {
            raw.parse::<u8>().map_err(|_| {
                OfdError::Invalid(format!(
                    "annotation {} has invalid PDFTextOpacity",
                    annotation.id
                ))
            })
        })
        .transpose()?;
    Ok(Some(PdfTextNoteData {
        icon,
        open,
        color,
        opacity,
    }))
}

fn pdf_popup_output_data(
    annotation: &AnnotationInfo,
    physical_box: [f64; 4],
) -> Result<Option<([f64; 4], bool)>, OfdError> {
    let boundary = annotation.parameters.get("PDFPopupBoundary");
    let open = annotation.parameters.get("PDFPopupOpen");
    let (Some(boundary), Some(open)) = (boundary, open) else {
        if boundary.is_some() || open.is_some() {
            return Err(OfdError::Invalid(format!(
                "annotation {} has incomplete PDF Popup metadata",
                annotation.id
            )));
        }
        return Ok(None);
    };
    let boundary = parse_box(boundary).ok_or_else(|| {
        OfdError::Invalid(format!(
            "annotation {} has invalid PDFPopupBoundary",
            annotation.id
        ))
    })?;
    let open = match open.as_str() {
        "true" => true,
        "false" => false,
        _ => {
            return Err(OfdError::Invalid(format!(
                "annotation {} has invalid PDFPopupOpen",
                annotation.id
            )))
        }
    };
    Ok(Some((pdf_link_rect(boundary, physical_box)?, open)))
}

fn pdf_text_markup_data(
    annotation: &AnnotationInfo,
    physical_box: [f64; 4],
    boundary: [f64; 4],
) -> Result<Option<PdfTextMarkupData>, OfdError> {
    let Some(raw_quads) = annotation.parameters.get("PDFMarkupQuads") else {
        return Ok(None);
    };
    let kind = match (
        annotation.annotation_type.as_str(),
        annotation.subtype.as_deref(),
    ) {
        ("Highlight", _) => AnnotationType::Highlight,
        ("Underline", _) | ("Path", Some("Underline")) => AnnotationType::Underline,
        ("StrikeOut", _) | ("Path", Some("StrikeOut")) => AnnotationType::StrikeOut,
        ("Squiggly", _) | ("Path", Some("Squiggly")) => AnnotationType::Squiggly,
        _ => {
            return Err(OfdError::Invalid(format!(
                "annotation {} has unsupported PDF markup type",
                annotation.id
            )))
        }
    };
    let values = raw_quads
        .split_whitespace()
        .take(80_001)
        .map(str::parse::<f64>)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| {
            OfdError::Invalid(format!(
                "annotation {} has invalid PDFMarkupQuads",
                annotation.id
            ))
        })?;
    if values.is_empty() || values.len() % 8 != 0 || values.len() > 80_000 {
        return Err(OfdError::Invalid(format!(
            "annotation {} has invalid PDFMarkupQuads",
            annotation.id
        )));
    }
    let mut quads = Vec::with_capacity(values.len());
    for values in values.chunks_exact(8) {
        let points = std::array::from_fn(|index| {
            [
                boundary[0] + values[index * 2] * boundary[2],
                boundary[1] + values[index * 2 + 1] * boundary[3],
            ]
        });
        if convex_quad_turn(points).is_none() {
            return Err(OfdError::Invalid(format!(
                "annotation {} has degenerate PDFMarkupQuads",
                annotation.id
            )));
        }
        quads.extend(pdf_link_quad(points, physical_box)?);
    }
    let raw_color = annotation.parameters.get("PDFMarkupColor").ok_or_else(|| {
        OfdError::Invalid(format!(
            "annotation {} has no PDFMarkupColor",
            annotation.id
        ))
    })?;
    let color = raw_color
        .split_whitespace()
        .map(str::parse::<u8>)
        .collect::<Result<Vec<_>, _>>()
        .map_err(|_| {
            OfdError::Invalid(format!(
                "annotation {} has invalid PDFMarkupColor",
                annotation.id
            ))
        })?;
    let color: [u8; 3] = color.try_into().map_err(|_| {
        OfdError::Invalid(format!(
            "annotation {} has invalid PDFMarkupColor",
            annotation.id
        ))
    })?;
    let opacity = annotation
        .parameters
        .get("PDFMarkupOpacity")
        .ok_or_else(|| {
            OfdError::Invalid(format!(
                "annotation {} has no PDFMarkupOpacity",
                annotation.id
            ))
        })?
        .parse::<u8>()
        .map_err(|_| {
            OfdError::Invalid(format!(
                "annotation {} has invalid PDFMarkupOpacity",
                annotation.id
            ))
        })?;
    Ok(Some(PdfTextMarkupData {
        kind,
        quads,
        color,
        opacity,
    }))
}

fn unique_pdf_annotation_name(base: &str, used: &mut HashSet<String>) -> String {
    if used.insert(base.to_owned()) {
        return base.to_owned();
    }
    for suffix in 2.. {
        let candidate = format!("{base}-{suffix}");
        if used.insert(candidate.clone()) {
            return candidate;
        }
    }
    unreachable!("annotation name suffixes are unbounded")
}

fn pdf_action_shapes(
    action: &PageObjectActionInfo,
    default_boundary: [f64; 4],
) -> Result<Vec<PdfLinkShape>, OfdError> {
    let Some(region) = &action.region else {
        return Ok(vec![PdfLinkShape {
            boundary: default_boundary,
            quad: None,
        }]);
    };
    let mut shapes = Vec::with_capacity(region.areas.len());
    for area in &region.areas {
        let mut start = area.start;
        let mut points = vec![start];
        let mut closed = false;
        for command in &area.commands {
            match command.kind.as_str() {
                "Move" if points.len() == 1 => {
                    start = command
                        .attributes
                        .get("Point1")
                        .and_then(|value| parse_numbers::<2>(value))
                        .ok_or_else(|| {
                            OfdError::Invalid("Action Region Move has invalid Point1".into())
                        })?;
                    points[0] = start;
                }
                "Line" if !closed => {
                    let point = command
                        .attributes
                        .get("Point1")
                        .and_then(|value| parse_numbers::<2>(value))
                        .ok_or_else(|| {
                            OfdError::Invalid("Action Region Line has invalid Point1".into())
                        })?;
                    points.push(point);
                }
                "Close" if !closed => closed = true,
                _ => {
                    return Err(OfdError::Invalid(
                        "nonrectangular Action Region cannot be exported to PDF".into(),
                    ))
                }
            }
        }
        if points.last() == Some(&start) {
            points.pop();
        }
        if !closed || points.len() != 4 {
            return Err(OfdError::Invalid(
                "nonrectangular Action Region cannot be exported to PDF".into(),
            ));
        }
        let min_x = points
            .iter()
            .map(|point| point[0])
            .fold(f64::INFINITY, f64::min);
        let max_x = points
            .iter()
            .map(|point| point[0])
            .fold(f64::NEG_INFINITY, f64::max);
        let min_y = points
            .iter()
            .map(|point| point[1])
            .fold(f64::INFINITY, f64::min);
        let max_y = points
            .iter()
            .map(|point| point[1])
            .fold(f64::NEG_INFINITY, f64::max);
        let corners = [
            [min_x, min_y],
            [max_x, min_y],
            [max_x, max_y],
            [min_x, max_y],
        ];
        let rectangle = corners.iter().all(|corner| points.contains(corner))
            && !points
                .iter()
                .zip(points.iter().cycle().skip(1))
                .take(4)
                .any(|(a, b)| a[0] != b[0] && a[1] != b[1]);
        let points: [[f64; 2]; 4] = points
            .try_into()
            .map_err(|_| OfdError::Invalid("Action Region Area is not a quadrilateral".into()))?;
        let Some(turn) = convex_quad_turn(points) else {
            return Err(OfdError::Invalid(
                "Action Region Area is not a convex quadrilateral".into(),
            ));
        };
        if max_x <= min_x || max_y <= min_y {
            return Err(OfdError::Invalid("Action Region Area has no area".into()));
        }
        let quad = if rectangle {
            None
        } else if turn > 0.0 {
            Some([points[0], points[3], points[2], points[1]])
        } else {
            Some([points[0], points[1], points[2], points[3]])
        };
        shapes.push(PdfLinkShape {
            boundary: [min_x, min_y, max_x - min_x, max_y - min_y],
            quad,
        });
    }
    if shapes.is_empty() {
        return Err(OfdError::Invalid("Action Region has no Area".into()));
    }
    Ok(shapes)
}

fn pdf_link_output_regions(
    action: &PageObjectActionInfo,
    boundary: [f64; 4],
    physical_box: [f64; 4],
    combine: bool,
) -> Result<Vec<PdfLinkOutputRegion>, OfdError> {
    let shapes = pdf_action_shapes(action, boundary)?;
    if combine && shapes.len() > 1 {
        let min_x = shapes
            .iter()
            .map(|shape| shape.boundary[0])
            .fold(f64::INFINITY, f64::min);
        let min_y = shapes
            .iter()
            .map(|shape| shape.boundary[1])
            .fold(f64::INFINITY, f64::min);
        let max_x = shapes
            .iter()
            .map(|shape| shape.boundary[0] + shape.boundary[2])
            .fold(f64::NEG_INFINITY, f64::max);
        let max_y = shapes
            .iter()
            .map(|shape| shape.boundary[1] + shape.boundary[3])
            .fold(f64::NEG_INFINITY, f64::max);
        let mut quads = Vec::with_capacity(shapes.len() * 8);
        for shape in shapes {
            let points = shape.quad.unwrap_or_else(|| {
                let [x, y, width, height] = shape.boundary;
                [
                    [x, y],
                    [x + width, y],
                    [x + width, y + height],
                    [x, y + height],
                ]
            });
            quads.extend(pdf_link_quad(points, physical_box)?);
        }
        return Ok(vec![PdfLinkOutputRegion {
            rect: pdf_link_rect([min_x, min_y, max_x - min_x, max_y - min_y], physical_box)?,
            quads: Some(quads),
        }]);
    }
    shapes
        .into_iter()
        .map(|shape| {
            Ok(PdfLinkOutputRegion {
                rect: pdf_link_rect(shape.boundary, physical_box)?,
                quads: shape
                    .quad
                    .map(|quad| pdf_link_quad(quad, physical_box).map(Vec::from))
                    .transpose()?,
            })
        })
        .collect()
}

fn layer_type_order(value: Option<&str>) -> Result<(&'static str, usize), OfdError> {
    match value.unwrap_or("Body").trim().to_ascii_lowercase().as_str() {
        "background" => Ok(("Background", 0)),
        "body" | "" => Ok(("Body", 1)),
        "foreground" => Ok(("Foreground", 2)),
        value => Err(OfdError::Invalid(format!("invalid layer Type: {value}"))),
    }
}

fn canonical_blend_mode(value: &str) -> Result<&'static str, OfdError> {
    match value.trim().to_ascii_lowercase().replace('-', "").as_str() {
        "normal" => Ok("Normal"),
        "multiply" => Ok("Multiply"),
        "screen" => Ok("Screen"),
        "overlay" => Ok("Overlay"),
        "darken" => Ok("Darken"),
        "lighten" => Ok("Lighten"),
        "colordodge" => Ok("ColorDodge"),
        "colorburn" => Ok("ColorBurn"),
        "hardlight" => Ok("HardLight"),
        "softlight" => Ok("SoftLight"),
        "difference" => Ok("Difference"),
        "exclusion" => Ok("Exclusion"),
        "hue" => Ok("Hue"),
        "saturation" => Ok("Saturation"),
        "color" => Ok("Color"),
        "luminosity" => Ok("Luminosity"),
        _ => Err(OfdError::Invalid("unsupported graphic BlendMode".into())),
    }
}

