impl PathStyle {
    fn color_xml(
        &self,
        prefix: &str,
        name: &str,
        color: Option<[u8; 3]>,
        alpha: Option<u8>,
    ) -> String {
        if color.is_none() && alpha.is_none() {
            return String::new();
        }
        let [r, g, b] = color.unwrap_or([0; 3]);
        let alpha = alpha.map_or_else(String::new, |value| format!(" Alpha=\"{value}\""));
        format!("<{prefix}{name} Value=\"{r} {g} {b}\"{alpha}/>")
    }

    fn validate_stroke(&self) -> Result<(), OfdError> {
        if self.dash_pattern.is_some() && self.dash_sequence.is_some() {
            return Err(OfdError::Invalid("path has two dash definitions".into()));
        }
        if !self.line_width.is_finite()
            || self.line_width <= 0.0
            || self
                .miter_limit
                .is_some_and(|value| !value.is_finite() || value <= 0.0)
            || self.dash_pattern.is_some_and(|values| {
                values
                    .iter()
                    .any(|value| !value.is_finite() || *value <= 0.0)
            })
            || self.dash_sequence.as_ref().is_some_and(|values| {
                values.is_empty()
                    || values.len() > 256
                    || values
                        .iter()
                        .any(|value| !value.is_finite() || *value <= 0.0)
            })
            || self.dash_offset.is_some_and(|value| !value.is_finite())
        {
            return Err(OfdError::Invalid("path stroke style is invalid".into()));
        }
        Ok(())
    }

    fn xml_attributes(&self) -> String {
        let mut attributes = String::new();
        if self.even_odd {
            attributes.push_str(" Rule=\"Even-Odd\"");
        }
        if let Some(value) = self.alpha {
            attributes.push_str(&format!(" Alpha=\"{value}\""));
        }
        if let Some(value) = self.cap {
            attributes.push_str(&format!(" Cap=\"{}\"", value.ofd_name()));
        }
        if let Some(value) = self.join {
            attributes.push_str(&format!(" Join=\"{}\"", value.ofd_name()));
        }
        if let Some(value) = self.miter_limit {
            attributes.push_str(&format!(" MiterLimit=\"{value}\""));
        }
        if let Some([dash, gap]) = self.dash_pattern {
            attributes.push_str(&format!(" DashPattern=\"{dash} {gap}\""));
        } else if let Some(values) = &self.dash_sequence {
            let sequence = values
                .iter()
                .map(f64::to_string)
                .collect::<Vec<_>>()
                .join(" ");
            attributes.push_str(&format!(" DashPattern=\"{sequence}\""));
        }
        if let Some(value) = self.dash_offset {
            attributes.push_str(&format!(" DashOffset=\"{value}\""));
        }
        attributes
    }
}

