    /// Set an annotation TextObject's font to a resource visible on its page.
    /// Shaped text may only retain its existing font because its glyph IDs are font-specific.
    pub fn set_annotation_text_font(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        object_id: &str,
        font_id: &str,
    ) -> Result<(), OfdError> {
        if font_id.trim().is_empty() {
            return Err(OfdError::Invalid("font ID is empty".into()));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        if !self
            .fonts_for_page(&page.path, page.document_index)?
            .iter()
            .any(|font| resource_id_key(&font.id) == resource_id_key(font_id))
        {
            return Err(OfdError::Invalid(format!(
                "font {font_id} is not available to the page"
            )));
        }
        self.edit_annotation_object_xml(page_index, annotation_id, object_id, |source, object| {
            if !is_ofd_element(object, "TextObject") {
                return Err(OfdError::Invalid(
                    "annotation object is not a TextObject".into(),
                ));
            }
            if object
                .attribute("Font")
                .is_some_and(|id| resource_id_key(id) == resource_id_key(font_id))
            {
                return Ok(source.to_owned());
            }
            if object
                .children()
                .any(|node| is_ofd_element(node, "CGTransform"))
            {
                return Err(OfdError::Invalid(
                    "cannot change shaped TextObject font without reshaping".into(),
                ));
            }
            let mut updated = source.to_owned();
            let replacement = format!("Font=\"{}\"", escape_xml(font_id));
            if let Some(attribute) = object.attribute_node("Font") {
                updated.replace_range(attribute.range(), &replacement);
            } else {
                let tag = qualified_tag(source, object)?;
                updated.insert_str(
                    object.range().start + 1 + tag.len(),
                    &format!(" {replacement}"),
                );
            }
            Ok(updated)
        })
    }

    /// Replace one TextCode run in an unshaped annotation TextObject.
    /// Character-count changes remeasure DeltaX; shaped text needs reshaping.
    pub fn set_annotation_text_code(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        object_id: &str,
        code_index: usize,
        text: &str,
    ) -> Result<(), OfdError> {
        if text.len() > 1_000_000 {
            return Err(OfdError::Limit("TextCode exceeds 1 MB".into()));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        let annotation = self.annotation_for_page(page, annotation_id)?;
        let source_path = annotation.source_path;
        let mut staged = self.clone();
        staged.edit_annotation_object_xml(
            page_index,
            annotation_id,
            object_id,
            |source, object| {
                if !is_ofd_element(object, "TextObject") {
                    return Err(OfdError::Invalid(
                        "annotation object is not a TextObject".into(),
                    ));
                }
                if object
                    .children()
                    .any(|node| is_ofd_element(node, "CGTransform"))
                {
                    return Err(OfdError::Invalid(
                        "cannot edit shaped TextObject without reshaping".into(),
                    ));
                }
                let code = object
                    .children()
                    .filter(|node| is_ofd_element(*node, "TextCode"))
                    .nth(code_index)
                    .ok_or_else(|| {
                        OfdError::Invalid(format!("TextCode index {code_index} is out of bounds"))
                    })?;
                let count_changed = decode_text_code(element_text(code).as_ref())?
                    .chars()
                    .count()
                    != text.chars().count();
                if count_changed && code.attribute("DeltaY").is_some() {
                    return Err(OfdError::Invalid(
                        "TextCode with DeltaY must keep its character count".into(),
                    ));
                }
                let measured_delta_x = if count_changed && code.attribute("DeltaX").is_some() {
                    let font_id = object.attribute("Font").ok_or_else(|| {
                        OfdError::Invalid("text object font is not defined".into())
                    })?;
                    let font = self
                        .fonts_for_page(&page.path, page.document_index)?
                        .into_iter()
                        .find(|font| resource_id_key(&font.id) == resource_id_key(font_id))
                        .ok_or_else(|| {
                            OfdError::Invalid("text object font is not defined".into())
                        })?;
                    let size = svg_number(object.attribute("Size"), 0.0)?;
                    if size <= 0.0 {
                        return Err(OfdError::Invalid("text object Size is invalid".into()));
                    }
                    Some(text_delta_x_attribute(self, &font, text, size)?)
                } else {
                    None
                };
                let mut text_nodes = code.children().filter(Node::is_text);
                let first = text_nodes.next();
                if text_nodes.next().is_some() {
                    return Err(OfdError::Invalid(
                        "TextCode has multiple text segments".into(),
                    ));
                }
                let escaped = escape_text_code(text);
                let mut updated = if let Some(old) = first {
                    let mut updated = source.to_owned();
                    updated.replace_range(old.range(), &escaped);
                    updated
                } else {
                    insert_xml_child(source, code, &escaped)?
                };
                if let Some(delta_x) = measured_delta_x {
                    let reparsed = parse_xml(&source_path, updated.as_bytes())?;
                    let item = reparsed
                        .root_element()
                        .children()
                        .find(|node| {
                            is_ofd_element(*node, "Annot")
                                && resource_id_matches(node.attribute("ID"), annotation_id)
                        })
                        .ok_or_else(|| {
                            OfdError::Invalid("annotation disappeared during edit".into())
                        })?;
                    let appearance = item
                        .children()
                        .find(|node| is_ofd_element(*node, "Appearance"))
                        .ok_or_else(|| OfdError::Invalid("annotation has no Appearance".into()))?;
                    let object = page_block_graphic_objects(appearance)
                        .find(|node| {
                            is_ofd_element(*node, "TextObject")
                                && resource_id_matches(node.attribute("ID"), object_id)
                        })
                        .ok_or_else(|| {
                            OfdError::Invalid("text object disappeared during edit".into())
                        })?;
                    let code = object
                        .children()
                        .filter(|node| is_ofd_element(*node, "TextCode"))
                        .nth(code_index)
                        .ok_or_else(|| {
                            OfdError::Invalid("TextCode disappeared during edit".into())
                        })?;
                    let attribute = code
                        .attributes()
                        .find(|attribute| {
                            attribute.name() == "DeltaX" && attribute.namespace().is_none()
                        })
                        .ok_or_else(|| {
                            OfdError::Invalid("DeltaX disappeared during edit".into())
                        })?;
                    updated.replace_range(attribute.range(), delta_x.trim_start());
                }
                parse_xml(&source_path, updated.as_bytes())?;
                Ok(updated)
            },
        )?;
        *self = staged;
        Ok(())
    }

    /// Replace the resource used by an annotation image or composite object.
    /// The new resource must be visible to the object's page.
    pub fn set_annotation_graphic_resource(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        object_id: &str,
        resource_id: &str,
    ) -> Result<(), OfdError> {
        if resource_id.trim().is_empty() {
            return Err(OfdError::Invalid("graphic resource ID is empty".into()));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        let matches = self
            .annotation_objects(page_index, annotation_id)?
            .into_iter()
            .filter(|object| resource_id_matches(object.id.as_deref(), object_id))
            .collect::<Vec<_>>();
        let [object] = matches.as_slice() else {
            return Err(OfdError::Invalid(format!(
                "annotation object {object_id} is missing or ambiguous"
            )));
        };
        match object.kind.as_str() {
            "ImageObject" => {
                self.validate_media_action_target(page_index, resource_id, "Image")?;
                self.maskable_media_for_page(&page.path, page.document_index, resource_id)?;
            }
            "CompositeObject" => {
                if !self
                    .page_resource_elements(
                        &page.path,
                        page.document_index,
                        "CompositeGraphicUnit",
                    )?
                    .contains_key(&resource_id_key(resource_id))
                {
                    return Err(OfdError::Invalid(format!(
                        "composite resource {resource_id} was not found"
                    )));
                }
            }
            _ => {
                return Err(OfdError::Invalid(
                    "annotation object is not an ImageObject or CompositeObject".into(),
                ));
            }
        }
        self.edit_annotation_object_xml(page_index, annotation_id, object_id, |source, node| {
            if node.tag_name().name() != object.kind {
                return Err(OfdError::Invalid("annotation object kind changed".into()));
            }
            let mut updated = source.to_owned();
            let attribute = format!("ResourceID=\"{}\"", escape_xml(resource_id));
            if let Some(old) = node.attribute_node("ResourceID") {
                updated.replace_range(old.range(), &attribute);
            } else {
                let tag = qualified_tag(source, node)?;
                updated.insert_str(node.range().start + 1 + tag.len(), &format!(" {attribute}"));
            }
            Ok(updated)
        })
    }

    /// Append ordered path, text, image, or composite objects to an existing appearance.
    /// Returns their allocated object IDs. The whole edit is atomic.
    pub fn append_annotation_objects(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        objects: &[AnnotationGraphic],
    ) -> Result<Vec<String>, OfdError> {
        if objects.is_empty() || objects.len() > 4096 {
            return Err(OfdError::Limit(
                "annotation needs 1..4096 new objects".into(),
            ));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        let matches = self
            .annotations()?
            .into_iter()
            .filter(|annotation| {
                annotation.document_index == page.document_index
                    && same_page_id(&annotation.page_id, &page.id)
                    && resource_id_key(&annotation.id) == resource_id_key(annotation_id)
            })
            .collect::<Vec<_>>();
        let [target] = matches.as_slice() else {
            return Err(OfdError::Invalid(format!(
                "annotation {annotation_id} is missing or ambiguous"
            )));
        };
        let boundary = target
            .appearance_box
            .ok_or_else(|| OfdError::Invalid("annotation has no Appearance Boundary".into()))?;
        let current_count = self.annotation_objects(page_index, annotation_id)?.len();
        if current_count
            .checked_add(objects.len())
            .is_none_or(|count| count > 4096)
        {
            return Err(OfdError::Limit(
                "annotation has too many graphic objects".into(),
            ));
        }
        let mut staged = self.clone();
        let temporary_id = staged.add_mixed_annotation(page_index, boundary, objects)?;
        let temporary = staged
            .annotations()?
            .into_iter()
            .find(|annotation| {
                annotation.document_index == page.document_index
                    && same_page_id(&annotation.page_id, &page.id)
                    && resource_id_key(&annotation.id) == resource_id_key(&temporary_id)
            })
            .ok_or_else(|| OfdError::Invalid("temporary annotation was not found".into()))?;
        if temporary.source_path != target.source_path {
            return Err(OfdError::Invalid(
                "annotation page file changed during append".into(),
            ));
        }
        let bytes = staged.required_entry(&temporary.source_path)?;
        let source = std::str::from_utf8(bytes).map_err(|error| OfdError::Xml {
            path: temporary.source_path.clone(),
            message: error.to_string(),
        })?;
        let parsed = parse_xml(&temporary.source_path, bytes)?;
        let temporary_node = parsed
            .root_element()
            .children()
            .find(|node| {
                is_ofd_element(*node, "Annot")
                    && node.attribute("ID") == Some(temporary_id.as_str())
            })
            .ok_or_else(|| OfdError::Invalid("temporary annotation disappeared".into()))?;
        let appearance = temporary_node
            .children()
            .find(|node| is_ofd_element(*node, "Appearance"))
            .ok_or_else(|| OfdError::Invalid("temporary annotation has no Appearance".into()))?;
        let mut ids = Vec::with_capacity(objects.len());
        let mut graphics_xml = String::new();
        for object in page_block_graphic_objects(appearance) {
            ids.push(
                object
                    .attribute("ID")
                    .ok_or_else(|| OfdError::Invalid("temporary graphic has no ID".into()))?
                    .to_owned(),
            );
            graphics_xml.push_str(&source[object.range()]);
        }
        if ids.len() != objects.len() {
            return Err(OfdError::Invalid(
                "temporary annotation object count changed".into(),
            ));
        }
        staged.remove_annotation(page_index, &temporary_id)?;
        staged.edit_annotation_xml(page_index, annotation_id, |source, annotation| {
            let appearance = annotation
                .children()
                .find(|node| is_ofd_element(*node, "Appearance"))
                .ok_or_else(|| OfdError::Invalid("annotation has no Appearance".into()))?;
            insert_xml_child(source, appearance, &graphics_xml)
        })?;
        *self = staged;
        Ok(ids)
    }

    fn edit_annotation_object_xml(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        object_id: &str,
        edit: impl FnOnce(&str, Node<'_, '_>) -> Result<String, OfdError>,
    ) -> Result<(), OfdError> {
        if object_id.trim().is_empty() {
            return Err(OfdError::Invalid("annotation object ID is empty".into()));
        }
        self.edit_annotation_xml(page_index, annotation_id, |source, annotation| {
            let appearance = annotation
                .children()
                .find(|node| is_ofd_element(*node, "Appearance"))
                .ok_or_else(|| OfdError::Invalid("annotation has no Appearance".into()))?;
            let mut matches = page_block_graphic_objects(appearance)
                .filter(|node| resource_id_matches(node.attribute("ID"), object_id));
            let object = matches.next().ok_or_else(|| {
                OfdError::Invalid(format!("annotation object {object_id} was not found"))
            })?;
            if matches.next().is_some() {
                return Err(OfdError::Invalid(format!(
                    "annotation object {object_id} is ambiguous"
                )));
            }
            edit(source, object)
        })
    }

    fn set_annotation_object_attribute(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        object_id: &str,
        name: &str,
        value: Option<&str>,
    ) -> Result<(), OfdError> {
        self.edit_annotation_object_xml(page_index, annotation_id, object_id, |source, object| {
            let mut updated = source.to_owned();
            if let Some(attribute) = object.attribute_node(name) {
                let mut range = attribute.range();
                if let Some(value) = value {
                    updated.replace_range(range, &format!("{name}=\"{value}\""));
                } else {
                    if range.start > 0 && source.as_bytes()[range.start - 1].is_ascii_whitespace() {
                        range.start -= 1;
                    }
                    updated.replace_range(range, "");
                }
            } else if let Some(value) = value {
                let tag = qualified_tag(source, object)?;
                updated.insert_str(
                    object.range().start + 1 + tag.len(),
                    &format!(" {name}=\"{value}\""),
                );
            }
            Ok(updated)
        })
    }

    /// Remove one annotation from a page while retaining its XML file and ID.
    pub fn remove_annotation(
        &mut self,
        page_index: usize,
        annotation_id: &str,
    ) -> Result<(), OfdError> {
        if annotation_id.trim().is_empty() {
            return Err(OfdError::Invalid("annotation ID is empty".into()));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        self.ensure_unsigned_page(page)?;
        let matches: Vec<_> = self
            .annotations()?
            .into_iter()
            .filter(|item| {
                item.document_index == page.document_index
                    && same_page_id(&item.page_id, &page.id)
                    && resource_id_key(&item.id) == resource_id_key(annotation_id)
            })
            .collect();
        let [annotation] = matches.as_slice() else {
            return Err(OfdError::Invalid(if matches.is_empty() {
                format!(
                    "annotation {annotation_id} was not found on page {}",
                    page.id
                )
            } else {
                format!(
                    "annotation {annotation_id} is ambiguous on page {}",
                    page.id
                )
            }));
        };
        let path = &annotation.source_path;
        self.ensure_unsigned_entry(path)?;
        let bytes = self.required_entry(path)?;
        let parsed = parse_xml(path, bytes)?;
        let mut nodes = parsed.root_element().children().filter(|node| {
            is_ofd_element(*node, "Annot")
                && resource_id_matches(node.attribute("ID"), annotation_id)
        });
        let node = nodes.next().ok_or_else(|| {
            OfdError::Invalid(format!(
                "annotation {annotation_id} was not found in {path}"
            ))
        })?;
        if nodes.next().is_some() {
            return Err(OfdError::Invalid("annotation ID is ambiguous".into()));
        }
        let source = std::str::from_utf8(bytes).map_err(|error| OfdError::Xml {
            path: path.clone(),
            message: error.to_string(),
        })?;
        let mut updated = source.to_owned();
        updated.replace_range(node.range(), "");
        self.set_structured_entry(path, updated.into_bytes())
    }

