    /// Set an annotation appearance boundary in page millimeters.
    pub fn set_annotation_appearance_boundary(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        boundary: [f64; 4],
    ) -> Result<(), OfdError> {
        let [x, y, width, height] = boundary;
        if boundary.iter().any(|value| !value.is_finite()) || width <= 0.0 || height <= 0.0 {
            return Err(OfdError::Invalid(
                "annotation appearance Boundary has invalid dimensions".into(),
            ));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        let shape_paths = pdf_shape_data(&self.annotation_for_page(page, annotation_id)?)?
            .map(|shape| -> Result<Vec<String>, OfdError> {
                match shape.kind {
                    PdfShapeKind::Square => {
                        Ok(vec![pdf_shape_path("Square", width, height, shape.insets)?])
                    }
                    PdfShapeKind::Circle => {
                        Ok(vec![pdf_shape_path("Circle", width, height, shape.insets)?])
                    }
                    PdfShapeKind::Line => {
                        let [x1, y1, x2, y2] =
                            shape.line.expect("PDF Line endpoints were validated");
                        let endpoints = [x1 * width, y1 * height, x2 * width, y2 * height];
                        let (main, leaders) =
                            pdf_import::pdf_line_leader_paths(endpoints, shape.line_leader);
                        let mut paths = vec![format!(
                            "M {} {} L {} {}",
                            main[0], main[1], main[2], main[3]
                        )];
                        paths.extend(leaders);
                        if let Some(endings) = shape.line_endings {
                            for (index, ending) in endings.into_iter().enumerate() {
                                if let Some(AnnotationGraphic::Path(path)) =
                                    pdf_import::pdf_line_ending_graphic(
                                        ending,
                                        index,
                                        boundary,
                                        main,
                                        &PathStyle {
                                            line_width: shape.width,
                                            stroke_color: shape.stroke,
                                            fill_color: shape.fill,
                                            alpha: Some(shape.opacity),
                                            ..PathStyle::default()
                                        },
                                    )
                                {
                                    paths.push(path.commands);
                                }
                            }
                        }
                        Ok(paths)
                    }
                    PdfShapeKind::Ink => shape
                        .ink
                        .as_ref()
                        .ok_or_else(|| OfdError::Invalid("PDF Ink has no strokes".into()))?
                        .iter()
                        .map(|points| pdf_ink_path(points, width, height))
                        .collect(),
                    PdfShapeKind::Polygon | PdfShapeKind::PolyLine => {
                        let vertices = shape.vertices.as_ref().ok_or_else(|| {
                            OfdError::Invalid("PDF polygon has no vertices".into())
                        })?;
                        let mut paths = vec![pdf_poly_path(
                            vertices,
                            width,
                            height,
                            shape.kind == PdfShapeKind::Polygon,
                        )?];
                        if let Some(endings) = shape.line_endings {
                            let graphics = pdf_import::pdf_polyline_ending_graphics(
                                vertices,
                                boundary,
                                endings,
                                shape.width,
                                shape.stroke,
                                shape.fill,
                                shape.opacity,
                            );
                            paths.extend(graphics.into_iter().filter_map(|graphic| {
                                if let AnnotationGraphic::Path(path) = graphic {
                                    Some(path.commands)
                                } else {
                                    None
                                }
                            }));
                        }
                        Ok(paths)
                    }
                }
            })
            .transpose()?;
        self.edit_annotation_xml(page_index, annotation_id, |source, node| {
            let appearance = node
                .children()
                .find(|child| is_ofd_element(*child, "Appearance"))
                .ok_or_else(|| OfdError::Invalid("annotation has no Appearance".into()))?;
            let value = format!("{x} {y} {width} {height}");
            let mut updated = source.to_owned();
            let mut edits = Vec::new();
            if let Some(attribute) = appearance.attribute_node("Boundary") {
                edits.push((attribute.range(), format!("Boundary=\"{value}\"")));
            } else {
                let tag = qualified_tag(source, appearance)?;
                let position = appearance.range().start + 1 + tag.len();
                edits.push((position..position, format!(" Boundary=\"{value}\"")));
            }
            if let Some(path_data) = &shape_paths {
                let objects: Vec<_> = appearance
                    .children()
                    .filter(|child| is_ofd_element(*child, "PathObject"))
                    .collect();
                if objects.len() != path_data.len() {
                    return Err(OfdError::Invalid(
                        "PDF shape appearance PathObject count is invalid".into(),
                    ));
                }
                for (object, commands) in objects.into_iter().zip(path_data) {
                    let object_boundary = object.attribute_node("Boundary").ok_or_else(|| {
                        OfdError::Invalid("PDF shape PathObject has no Boundary".into())
                    })?;
                    edits.push((
                        object_boundary.range(),
                        format!("Boundary=\"0 0 {width} {height}\""),
                    ));
                    let data = descendant(object, "AbbreviatedData")
                        .and_then(|node| node.children().find(Node::is_text))
                        .ok_or_else(|| OfdError::Invalid("PDF shape has no path data".into()))?;
                    edits.push((data.range(), escape_xml(commands)));
                }
            }
            edits.sort_by_key(|(range, _)| std::cmp::Reverse(range.start));
            for (range, replacement) in edits {
                updated.replace_range(range, &replacement);
            }
            Ok(updated)
        })
    }

    fn set_annotation_string_attribute(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        name: &str,
        value: Option<&str>,
    ) -> Result<(), OfdError> {
        self.edit_annotation_xml(page_index, annotation_id, |source, node| {
            let mut updated = source.to_owned();
            if let Some(attribute) = node
                .attributes()
                .find(|attribute| attribute.name() == name && attribute.namespace().is_none())
            {
                let replacement = value.map_or(String::new(), |value| {
                    format!("{name}=\"{}\"", escape_xml(value))
                });
                updated.replace_range(attribute.range(), &replacement);
            } else if let Some(value) = value {
                let tag = qualified_tag(source, node)?;
                updated.insert_str(
                    node.range().start + 1 + tag.len(),
                    &format!(" {name}=\"{}\"", escape_xml(value)),
                );
            }
            Ok(updated)
        })
    }

    /// Set or remove the optional `Remark` content of an annotation.
    pub fn set_annotation_remark(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        remark: Option<&str>,
    ) -> Result<(), OfdError> {
        self.edit_annotation_xml(page_index, annotation_id, |source, node| {
            let mut updated = source.to_owned();
            let existing = node
                .children()
                .find(|child| is_ofd_element(*child, "Remark"));
            match (existing, remark) {
                (Some(existing), None) => updated.replace_range(existing.range(), ""),
                (Some(existing), Some(value)) => {
                    if source[existing.range()].trim_end().ends_with("/>") {
                        updated = insert_xml_child(source, existing, &escape_xml(value))?;
                    } else {
                        updated.replace_range(
                            element_content_range(existing, source)?,
                            &escape_xml(value),
                        );
                    }
                }
                (None, Some(value)) => {
                    let tag = qualified_tag(source, node)?;
                    let prefix = tag
                        .rsplit_once(':')
                        .map_or(String::new(), |(prefix, _)| format!("{prefix}:"));
                    let child = format!("<{prefix}Remark>{}</{prefix}Remark>", escape_xml(value));
                    let position = node
                        .children()
                        .find(|child| is_ofd_element(*child, "Appearance"))
                        .map_or(node.range().end, |appearance| appearance.range().start);
                    if position == node.range().end {
                        updated = insert_xml_child(source, node, &child)?;
                    } else {
                        updated.insert_str(position, &child);
                    }
                }
                (None, None) => {}
            }
            Ok(updated)
        })
    }

    /// Add or replace one named annotation parameter.
    pub fn set_annotation_parameter(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        name: &str,
        value: &str,
    ) -> Result<(), OfdError> {
        if name.trim().is_empty() {
            return Err(OfdError::Invalid(
                "annotation Parameter Name is empty".into(),
            ));
        }
        self.edit_annotation_xml(page_index, annotation_id, |source, node| {
            let list = node.children().find(|child| is_ofd_element(*child, "Parameters"));
            if let Some(list) = list {
                let matches: Vec<_> = list.children().filter(|child| {
                    is_ofd_element(*child, "Parameter") && child.attribute("Name") == Some(name)
                }).collect();
                match matches.as_slice() {
                    [parameter] => {
                        let mut updated = source.to_owned();
                        if source[parameter.range()].trim_end().ends_with("/>") {
                            insert_xml_child(source, *parameter, &escape_xml(value))
                        } else {
                            updated.replace_range(
                                element_content_range(*parameter, source)?,
                                &escape_xml(value),
                            );
                            Ok(updated)
                        }
                    }
                    [] => {
                        let tag = qualified_tag(source, list)?;
                        let prefix = tag.rsplit_once(':').map_or(String::new(), |(prefix, _)| format!("{prefix}:"));
                        let child = format!("<{prefix}Parameter Name=\"{}\">{}</{prefix}Parameter>", escape_xml(name), escape_xml(value));
                        insert_xml_child(source, list, &child)
                    }
                    _ => Err(OfdError::Invalid(format!("annotation Parameter {name} is ambiguous"))),
                }
            } else {
                let tag = qualified_tag(source, node)?;
                let prefix = tag.rsplit_once(':').map_or(String::new(), |(prefix, _)| format!("{prefix}:"));
                let child = format!("<{prefix}Parameters><{prefix}Parameter Name=\"{}\">{}</{prefix}Parameter></{prefix}Parameters>", escape_xml(name), escape_xml(value));
                let mut updated = source.to_owned();
                if let Some(appearance) = node.children().find(|child| is_ofd_element(*child, "Appearance")) {
                    updated.insert_str(appearance.range().start, &child);
                    Ok(updated)
                } else {
                    insert_xml_child(source, node, &child)
                }
            }
        })
    }

    /// Remove one named annotation parameter.
    pub fn remove_annotation_parameter(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        name: &str,
    ) -> Result<(), OfdError> {
        if name.trim().is_empty() {
            return Err(OfdError::Invalid(
                "annotation Parameter Name is empty".into(),
            ));
        }
        self.edit_annotation_xml(page_index, annotation_id, |source, node| {
            let parameter = node
                .children()
                .find(|child| is_ofd_element(*child, "Parameters"))
                .and_then(|list| {
                    list.children().find(|child| {
                        is_ofd_element(*child, "Parameter") && child.attribute("Name") == Some(name)
                    })
                })
                .ok_or_else(|| {
                    OfdError::Invalid(format!("annotation Parameter {name} was not found"))
                })?;
            let mut updated = source.to_owned();
            updated.replace_range(parameter.range(), "");
            Ok(updated)
        })
    }

    fn set_annotation_bool_attribute(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        name: &str,
        value: bool,
    ) -> Result<(), OfdError> {
        self.edit_annotation_xml(page_index, annotation_id, |source, node| {
            let mut updated = source.to_owned();
            let value = if value { "true" } else { "false" };
            if let Some(attribute) = node
                .attributes()
                .find(|attribute| attribute.name() == name && attribute.namespace().is_none())
            {
                updated.replace_range(attribute.range(), &format!("{name}=\"{value}\""));
            } else {
                let tag = qualified_tag(source, node)?;
                updated.insert_str(
                    node.range().start + 1 + tag.len(),
                    &format!(" {name}=\"{value}\""),
                );
            }
            Ok(updated)
        })
    }

    fn edit_annotation_xml(
        &mut self,
        page_index: usize,
        annotation_id: &str,
        edit: impl FnOnce(&str, Node<'_, '_>) -> Result<String, OfdError>,
    ) -> Result<(), OfdError> {
        if annotation_id.trim().is_empty() {
            return Err(OfdError::Invalid("annotation ID is empty".into()));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        self.ensure_unsigned_page(page)?;
        let matches: Vec<_> = self
            .annotations()?
            .into_iter()
            .filter(|annotation| {
                annotation.document_index == page.document_index
                    && same_page_id(&annotation.page_id, &page.id)
                    && resource_id_key(&annotation.id) == resource_id_key(annotation_id)
            })
            .collect();
        let [annotation] = matches.as_slice() else {
            return Err(OfdError::Invalid(format!(
                "annotation {annotation_id} is missing or ambiguous on page {}",
                page.id
            )));
        };
        self.ensure_unsigned_entry(&annotation.source_path)?;
        let bytes = self.required_entry(&annotation.source_path)?;
        let parsed = parse_xml(&annotation.source_path, bytes)?;
        let mut nodes = parsed.root_element().children().filter(|node| {
            is_ofd_element(*node, "Annot")
                && resource_id_matches(node.attribute("ID"), annotation_id)
        });
        let node = nodes
            .next()
            .ok_or_else(|| OfdError::Invalid(format!("annotation {annotation_id} is missing")))?;
        if nodes.next().is_some() {
            return Err(OfdError::Invalid(format!(
                "annotation {annotation_id} is ambiguous"
            )));
        }
        let source = std::str::from_utf8(bytes).map_err(|error| OfdError::Xml {
            path: annotation.source_path.clone(),
            message: error.to_string(),
        })?;
        let updated = edit(source, node)?;
        self.set_structured_entry(&annotation.source_path, updated.into_bytes())
    }

