    pub fn add_page_object_goto_action(
        &mut self,
        page_index: usize,
        object_id: &str,
        destination: DestinationInfo,
    ) -> Result<(), OfdError> {
        if object_id.trim().is_empty() {
            return Err(OfdError::Invalid("page object ID is empty".into()));
        }
        self.validate_page_destination(page_index, &destination)?;
        self.append_page_object_action(page_index, object_id, |prefix| {
            format!(
                "<{prefix}Goto>{}</{prefix}Goto>",
                destination_xml(&destination, prefix)
            )
        })
    }

    /// Append a click action that jumps to a named bookmark in the same document.
    pub fn add_page_object_bookmark_action(
        &mut self,
        page_index: usize,
        object_id: &str,
        bookmark_name: &str,
    ) -> Result<(), OfdError> {
        if object_id.trim().is_empty() || bookmark_name.trim().is_empty() {
            return Err(OfdError::Invalid(
                "object ID and bookmark name must be nonempty".into(),
            ));
        }
        let pages = self.pages()?;
        let page = pages.get(page_index).ok_or(OfdError::PageIndex {
            index: page_index,
            count: pages.len(),
        })?;
        if !self.bookmarks()?.iter().any(|bookmark| {
            bookmark.document_index == page.document_index && bookmark.name == bookmark_name
        }) {
            return Err(OfdError::Invalid(format!(
                "bookmark {bookmark_name} was not found in the same document"
            )));
        }
        self.append_page_object_action(page_index, object_id, |prefix| {
            format!(
                "<{prefix}Goto><{prefix}Bookmark Name=\"{}\"/></{prefix}Goto>",
                escape_xml(bookmark_name)
            )
        })
    }

