    #[test]
    fn package_header_roundtrip_and_rejects_protected_edits() {
        let mut document = OfdDocument::new();
        assert_eq!(
            document.package_info().unwrap(),
            PackageInfo {
                version: Some("1.2".into()),
                doc_type: Some("OFD".into()),
            }
        );
        document.set_package_header("1.3 & beta", "OFD-A").unwrap();
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(
            reopened.package_info().unwrap(),
            PackageInfo {
                version: Some("1.3 & beta".into()),
                doc_type: Some("OFD-A".into()),
            }
        );
        let original = document.entry("OFD.xml").unwrap().unwrap().to_vec();
        assert!(document.set_package_header("", "OFD").is_err());
        assert_eq!(document.entry("OFD.xml").unwrap().unwrap(), original);
        document
            .set_entry("OFDEntries.xml", b"<DocEntries/>".to_vec())
            .unwrap();
        assert!(document.set_package_header("1.2", "OFD").is_err());
        assert_eq!(document.entry("OFD.xml").unwrap().unwrap(), original);
    }

    #[test]
    fn package_header_validation_accepts_legacy_versions_and_reports_invalid_attributes() {
        let mut document = OfdDocument::new();
        for version in ["1.0", "1.1", "1.2"] {
            document.set_package_header(version, "OFD").unwrap();
            assert!(
                !document.validate_references().unwrap().iter().any(|issue| {
                    issue.code == "invalid_package_version" || issue.code == "invalid_document_type"
                })
            );
        }
        document.set_package_header("bad", "OFD-X").unwrap();
        let issues = document.validate_references().unwrap();
        assert!(issues
            .iter()
            .any(|issue| issue.code == "invalid_package_version"));
        assert!(issues
            .iter()
            .any(|issue| issue.code == "invalid_document_type"));

        let source = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap()).unwrap();
        let without_header = source
            .replace("Version=\"bad\" ", "")
            .replace("DocType=\"OFD-X\"", "");
        document
            .set_entry("OFD.xml", without_header.into_bytes())
            .unwrap();
        let issues = document.validate_references().unwrap();
        assert!(issues
            .iter()
            .any(|issue| issue.code == "invalid_package_version"));
        assert!(issues
            .iter()
            .any(|issue| issue.code == "invalid_document_type"));
    }

