    #[test]
    fn escaped_text_code_is_used_by_extraction_search_and_svg() {
        let mut document = OfdDocument::new();
        document.add_text_page("AB", 100.0, 100.0).unwrap();
        let path = "Doc_0/Pages/Page_0/Content.xml";
        let source = std::str::from_utf8(document.entry(path).unwrap().unwrap()).unwrap();
        let updated = source.replace(">AB</ofd:TextCode>", r">A\0020B</ofd:TextCode>");
        assert_ne!(updated, source);
        document.set_entry(path, updated.into_bytes()).unwrap();
        assert_eq!(document.page_text(0).unwrap(), ["A B"]);
        assert_eq!(
            document.page_text_objects(0).unwrap()[0].codes[0].text,
            "A B"
        );
        assert_eq!(document.keyword_positions(&["A B"], None).unwrap().len(), 1);
        assert!(document.page_svg(0).unwrap().contains(">A B</text>"));
        assert!(document.validate_references().unwrap().is_empty());

        let mut literal = OfdDocument::new();
        literal.add_text_page(r"\0041", 100.0, 100.0).unwrap();
        assert_eq!(literal.page_text(0).unwrap(), [r"\0041"]);
        assert_eq!(
            literal.keyword_positions(&[r"\0041"], None).unwrap().len(),
            1
        );

        let mut control = OfdDocument::new();
        control.add_text_page("A\0B", 100.0, 100.0).unwrap();
        let page_xml = std::str::from_utf8(control.entry(path).unwrap().unwrap()).unwrap();
        assert!(page_xml.contains(r"A\0000B"));
        assert_eq!(control.page_text(0).unwrap(), ["A\0B"]);
        let svg = control.page_svg(0).unwrap();
        assert!(svg.contains("A�B"));
        XmlDocument::parse(&svg).unwrap();
        let id = control.page_text_objects(0).unwrap()[0].id.clone().unwrap();
        control.set_page_text_code(0, &id, 0, "C\0D").unwrap();
        control
            .append_page_text_code(0, &id, "E\0F", &TextCodeLayout::default())
            .unwrap();
        assert_eq!(control.page_text(0).unwrap(), ["C\0D", "E\0F"]);

        let mut carriage_return = OfdDocument::new();
        carriage_return.add_text_page("A\rB", 100.0, 100.0).unwrap();
        let reopened = OfdDocument::from_bytes(&carriage_return.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["A\rB"]);
    }

    #[test]
    fn cg_transforms_reject_overlapping_character_ranges() {
        let cases = [
            ("<CGTransform CodePosition=\"0\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>10</Glyphs></CGTransform><CGTransform CodePosition=\"2\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>11</Glyphs></CGTransform>", true),
            ("<CGTransform CodePosition=\"2\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>10</Glyphs></CGTransform><CGTransform CodePosition=\"0\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>11</Glyphs></CGTransform>", true),
            ("<CGTransform CodePosition=\"0\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>10</Glyphs></CGTransform><CGTransform CodePosition=\"1\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>11</Glyphs></CGTransform>", false),
            ("<CGTransform CodePosition=\"1\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>10</Glyphs></CGTransform><CGTransform CodePosition=\"1\" CodeCount=\"2\" GlyphCount=\"1\"><Glyphs>11</Glyphs></CGTransform>", false),
        ];
        for (transforms, valid) in cases {
            let xml = format!("<TextObject><TextCode>abcd</TextCode>{transforms}</TextObject>");
            let parsed = XmlDocument::parse(&xml).unwrap();
            let result = parse_cg_transforms(parsed.root_element());
            assert_eq!(result.is_ok(), valid, "{xml}");
        }

        let mut document = OfdDocument::new();
        document.add_text_page("abcd", 100.0, 100.0).unwrap();
        let path = "Doc_0/Pages/Page_0/Content.xml";
        let source = std::str::from_utf8(document.entry(path).unwrap().unwrap()).unwrap();
        let overlapping = source.replace(
            "</ofd:TextObject>",
            "<ofd:CGTransform CodePosition=\"0\" CodeCount=\"2\" GlyphCount=\"1\"><ofd:Glyphs>10</ofd:Glyphs></ofd:CGTransform><ofd:CGTransform CodePosition=\"1\" CodeCount=\"2\" GlyphCount=\"1\"><ofd:Glyphs>11</ofd:Glyphs></ofd:CGTransform></ofd:TextObject>",
        );
        document.set_entry(path, overlapping.into_bytes()).unwrap();
        assert!(matches!(
            document.page_text_objects(0),
            Err(OfdError::Invalid(message)) if message.contains("overlap")
        ));
        assert!(matches!(
            document.page_svg(0),
            Err(OfdError::Invalid(message)) if message.contains("overlap")
        ));
    }

