    fn font_with_test_kerning(font: &[u8], left: char, right: char) -> Vec<u8> {
        let face = ttf_parser::Face::parse(font, 0).unwrap();
        let left_id = face.glyph_index(left).unwrap().0;
        let right_id = face.glyph_index(right).unwrap().0;
        let adjustment = -i16::try_from(face.units_per_em() / 4).unwrap();
        let table_count = u16::from_be_bytes([font[4], font[5]]) as usize;
        let old_directory_end = 12 + table_count * 16;
        let table_offset = (font.len() + 16 + 3) & !3;
        let mut result = Vec::with_capacity(table_offset + 24);
        result.extend_from_slice(&font[..12]);
        result[4..6].copy_from_slice(&u16::try_from(table_count + 1).unwrap().to_be_bytes());
        for record in font[12..old_directory_end].chunks_exact(16) {
            let mut record = record.to_vec();
            let offset = u32::from_be_bytes(record[8..12].try_into().unwrap()) + 16;
            record[8..12].copy_from_slice(&offset.to_be_bytes());
            result.extend_from_slice(&record);
        }
        result.extend_from_slice(b"kern");
        result.extend_from_slice(&0u32.to_be_bytes());
        result.extend_from_slice(&u32::try_from(table_offset).unwrap().to_be_bytes());
        result.extend_from_slice(&24u32.to_be_bytes());
        result.extend_from_slice(&font[old_directory_end..]);
        result.resize(table_offset, 0);
        for value in [0u16, 1, 0, 20, 1, 1, 6, 0, 0, left_id, right_id] {
            result.extend_from_slice(&value.to_be_bytes());
        }
        result.extend_from_slice(&adjustment.to_be_bytes());
        result
    }

    #[test]
    fn flowed_text_applies_embedded_font_pair_kerning_to_layout_and_delta_x() {
        let original =
            include_bytes!("../../../../ofdrw-layout/src/test/resources/simhei-cut1.ttf");
        let patched = font_with_test_kerning(original, 'H', 'W');
        let mut document = OfdDocument::new();
        let font_id = document
            .add_embedded_font("Kerning Test", &patched)
            .unwrap();
        let font = document
            .fonts()
            .unwrap()
            .into_iter()
            .find(|font| font.id == font_id.to_string())
            .unwrap();
        let metrics = flow_font_metrics(&document, &font, "HW").unwrap();
        let first = metrics.advance('H');
        let second = metrics.advance('W');
        let adjustment = metrics.kerning('H', 'W');
        assert!(adjustment < 0.0);
        let width = (first + second + adjustment / 2.0) * 5.0;
        let style = FlowTextStyle {
            page_size: [width + 10.0, 20.0],
            margins: [5.0; 4],
            font_id: Some(font_id.to_string()),
            ..FlowTextStyle::default()
        };
        assert_eq!(
            document.add_flowed_text(0, "HW", style.clone()).unwrap(),
            [0]
        );
        assert_eq!(document.page_text(0).unwrap(), ["HW"]);
        let codes = &document.page_text_objects(0).unwrap()[0].codes;
        let delta: f64 = codes[0].delta_x.as_ref().unwrap().parse().unwrap();
        assert!((delta - (first + adjustment) * 5.0).abs() < 1e-9);
        let mut kept = FlowSpan::new("HW");
        kept.keep_together = true;
        assert_eq!(
            document
                .add_flowed_spans(0, &[kept], style.clone())
                .unwrap(),
            [1]
        );
        assert_eq!(document.page_text(1).unwrap(), ["HW"]);
        let codes = &document.page_text_objects(1).unwrap()[0].codes;
        let styled_delta: f64 = codes[0].delta_x.as_ref().unwrap().parse().unwrap();
        assert!((styled_delta - delta).abs() < 1e-9);
        assert_eq!(
            document
                .add_flowed_spans(0, &[FlowSpan::new("H"), FlowSpan::new("W")], style)
                .unwrap(),
            [2, 3]
        );
        assert_eq!(document.page_text(2).unwrap(), ["H"]);
        assert_eq!(document.page_text(3).unwrap(), ["W"]);
    }

    #[test]
    fn flowed_text_wraps_glyphs_and_preserves_spaces() {
        let advances = "abc def中".chars().map(|ch| (ch, 1.0)).collect();
        let metrics = FlowFontMetrics {
            advances,
            kerning: HashMap::new(),
        };
        let lines = wrap_flow_lines("abc def\n中\n\nabcdef", 4.0, 0.0, &metrics, false).unwrap();
        assert_eq!(
            lines
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>(),
            ["abc ", "def", "中", "", "abcd", "ef"]
        );
        assert_eq!(lines[0].width, 4.0);
        let leading = wrap_flow_lines(" ab ", 3.0, 0.0, &metrics, false).unwrap();
        assert_eq!(leading[0].text, " ab");
        assert_eq!(leading[1].text, " ");
    }

    #[test]
    fn flowed_text_never_splits_a_grapheme_cluster() {
        let metrics = FlowFontMetrics {
            advances: [('X', 0.3), ('A', 0.5), ('\u{301}', 0.5), ('B', 0.4)]
                .into_iter()
                .collect(),
            kerning: HashMap::new(),
        };
        let lines = wrap_flow_lines("XA\u{301}B", 1.0, 0.0, &metrics, false).unwrap();
        assert_eq!(
            lines
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>(),
            ["X", "A\u{301}", "B"]
        );
        assert_eq!(lines[1].width, 1.0);
        assert!(wrap_flow_lines("A\u{301}", 0.9, 0.0, &metrics, false).is_err());

        let emoji = FlowFontMetrics {
            advances: [('X', 0.3), ('👩', 0.3), ('\u{200d}', 0.3), ('💻', 0.3)]
                .into_iter()
                .collect(),
            kerning: HashMap::new(),
        };
        let lines = wrap_flow_lines("X👩\u{200d}💻", 0.9, 0.0, &emoji, false).unwrap();
        assert_eq!(lines[0].text, "X");
        assert_eq!(lines[1].text, "👩\u{200d}💻");
    }

    #[test]
    fn flowed_text_prefers_unicode_word_breaks_before_emergency_wrap() {
        let metrics = FlowFontMetrics {
            advances: "helo wrd".chars().map(|ch| (ch, 1.0)).collect(),
            kerning: HashMap::new(),
        };
        let lines = wrap_flow_lines("hello world", 8.0, 0.0, &metrics, false).unwrap();
        assert_eq!(
            lines
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>(),
            ["hello ", "world"]
        );
        assert_eq!(lines[0].width, 6.0);
        let long_word = wrap_flow_lines("helloworld", 8.0, 0.0, &metrics, false).unwrap();
        assert_eq!(
            long_word
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>(),
            ["hellowor", "ld"]
        );
    }

    #[test]
    fn flowed_text_recognizes_unicode_hard_breaks_and_crlf_as_one_break() {
        let text = "A\r\nB\u{000b}C\u{000c}D\u{0085}E\u{2028}F\u{2029}G\rH\nI\n";
        assert_eq!(
            flow_paragraphs(text),
            ["A", "B", "C", "D", "E", "F", "G", "H", "I"]
        );
        assert!(flow_paragraphs("\r\n\u{2028}").is_empty());
        assert_eq!(flow_paragraphs("\r\nA\r\n"), ["", "A"]);

        let metrics = FlowFontMetrics {
            advances: "ABCDEFGHI".chars().map(|ch| (ch, 1.0)).collect(),
            kerning: HashMap::new(),
        };
        let lines = wrap_flow_lines(text, 10.0, 0.0, &metrics, false).unwrap();
        assert_eq!(
            lines
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>(),
            ["A", "B", "C", "D", "E", "F", "G", "H", "I"]
        );

        let font = include_bytes!("../tests/fixtures/dejavu-serif.ttf");
        let face = rustybuzz::Face::from_slice(font, 0).unwrap();
        let shaped =
            wrap_shaped_flow_lines("A\r\nB\u{2028}C", 50.0, 0.0, 5.0, &face, false, None).unwrap();
        assert_eq!(
            shaped
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>(),
            ["A", "B", "C"]
        );
    }

    #[test]
    fn styled_flow_recognizes_hard_breaks_across_spans() {
        let spans = [FlowSpan::new("A\r"), FlowSpan::new("\nB\u{2028}C")];
        let paragraphs = flow_styled_paragraph_chars(&spans);
        let text = paragraphs
            .iter()
            .map(|paragraph| paragraph.iter().map(|(ch, _)| *ch).collect::<String>())
            .collect::<Vec<_>>();
        assert_eq!(text, ["A", "B", "C"]);
        assert_eq!(paragraphs[0][0].1, 0);
        assert_eq!(paragraphs[1][0].1, 1);

        let mut first = FlowSpan::new("A\r");
        first.line_break_after = true;
        let paragraphs = flow_styled_paragraph_chars(&[first, FlowSpan::new("\nB")]);
        assert_eq!(paragraphs.len(), 2);
        assert_eq!(paragraphs[1][0].0, 'B');
    }

    #[test]
    fn shaped_flow_prefers_unicode_word_breaks() {
        let font = include_bytes!("../tests/fixtures/dejavu-serif.ttf");
        let face = rustybuzz::Face::from_slice(font, 0).unwrap();
        let size = 5.0;
        let lower = shaped_text_width(&face, "hello wo", size, None).unwrap();
        let upper = shaped_text_width(&face, "hello wor", size, None).unwrap();
        assert!(upper > lower);
        let available = (lower + upper) / 2.0;
        assert!(shaped_text_width(&face, "world", size, None).unwrap() < available);
        let lines = wrap_shaped_flow_lines("hello world", available, 0.0, size, &face, false, None)
            .unwrap();
        assert_eq!(
            lines
                .iter()
                .map(|line| line.text.as_str())
                .collect::<Vec<_>>(),
            ["hello ", "world"]
        );
    }

    #[test]
    fn shaped_styled_flow_prefers_word_breaks_and_handles_hard_breaks() {
        let font = include_bytes!("../tests/fixtures/dejavu-serif.ttf");
        let face = rustybuzz::Face::from_slice(font, 0).unwrap();
        let size = 5.0;
        let lower = shaped_text_width(&face, "hello wo", size, None).unwrap();
        let upper = shaped_text_width(&face, "hello wor", size, None).unwrap();
        let mut document = OfdDocument::new();
        let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
        let mut style = FlowTextStyle {
            page_size: [(lower + upper) / 2.0 + 2.0, 30.0],
            margins: [1.0; 4],
            font_size: size,
            line_height: 6.0,
            font_id: Some(font_id.to_string()),
            shape: true,
            ..FlowTextStyle::default()
        };
        let spans = [FlowSpan::new("hello "), FlowSpan::new("world")];
        assert_eq!(
            document.add_flowed_spans(0, &spans, style.clone()).unwrap(),
            [0]
        );
        assert_eq!(document.page_text(0).unwrap(), ["hello ", "world"]);

        style.page_size[0] = 50.0;
        let spans = [FlowSpan::new("A\r"), FlowSpan::new("\nB\u{2028}C")];
        assert_eq!(
            document.add_flowed_spans(0, &spans, style.clone()).unwrap(),
            [1]
        );
        assert_eq!(document.page_text(1).unwrap(), ["A", "B", "C"]);

        let spans = [FlowSpan::new("A"), FlowSpan::new("\u{301}")];
        assert_eq!(document.add_flowed_spans(0, &spans, style).unwrap(), [2]);
        assert_eq!(document.page_text(2).unwrap(), ["A\u{301}"]);
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["hello ", "world"]);
        assert_eq!(reopened.page_text(1).unwrap(), ["A", "B", "C"]);
        assert_eq!(reopened.page_text(2).unwrap(), ["A\u{301}"]);
    }

    #[test]
    fn shaped_styled_flow_keeps_a_span_that_starts_inside_a_grapheme() {
        let font = include_bytes!("../tests/fixtures/dejavu-serif.ttf");
        let face = rustybuzz::Face::from_slice(font, 0).unwrap();
        let size = 5.0;
        let prefix = shaped_text_width(&face, "XA\u{301}", size, None).unwrap();
        let combined = shaped_text_width(&face, "XA\u{301}B", size, None).unwrap();
        let kept = shaped_text_width(&face, "A\u{301}B", size, None).unwrap();
        let width = (prefix + combined) / 2.0;
        assert!(prefix < width && kept < width && combined > width);

        let mut document = OfdDocument::new();
        let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
        let style = FlowTextStyle {
            page_size: [width + 2.0, 20.0],
            margins: [1.0; 4],
            font_size: size,
            line_height: 6.0,
            font_id: Some(font_id.to_string()),
            shape: true,
            ..FlowTextStyle::default()
        };
        let first = FlowSpan::new("XA");
        let mut second = FlowSpan::new("\u{301}B");
        second.keep_together = true;
        assert_eq!(
            document
                .add_flowed_spans(0, &[first, second], style)
                .unwrap(),
            [0]
        );
        assert_eq!(document.page_text(0).unwrap(), ["X", "A\u{301}", "B"]);
        let objects = document.page_text_objects(0).unwrap();
        assert_eq!(objects[0].boundary.unwrap()[1], 1.0);
        assert_eq!(objects[1].boundary.unwrap()[1], 7.0);
        assert_eq!(objects[2].boundary.unwrap()[1], 7.0);
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["X", "A\u{301}", "B"]);
    }

    #[test]
    fn shaped_styled_flow_merges_overlapping_kept_spans() {
        let font = include_bytes!("../tests/fixtures/dejavu-serif.ttf");
        let face = rustybuzz::Face::from_slice(font, 0).unwrap();
        let size = 5.0;
        let first_width = shaped_text_width(&face, "XA\u{301}", size, None).unwrap();
        let second_width = shaped_text_width(&face, "A\u{301}B", size, None).unwrap();
        let combined_width = shaped_text_width(&face, "XA\u{301}B", size, None).unwrap();
        let width = first_width.max(second_width) + 0.1;
        assert!(combined_width > width);

        let mut document = OfdDocument::new();
        let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
        let style = FlowTextStyle {
            page_size: [width + 2.0, 20.0],
            margins: [1.0; 4],
            font_size: size,
            line_height: 6.0,
            font_id: Some(font_id.to_string()),
            shape: true,
            ..FlowTextStyle::default()
        };
        let mut first = FlowSpan::new("XA");
        first.keep_together = true;
        let mut second = FlowSpan::new("\u{301}B");
        second.keep_together = true;
        let before = document.to_bytes().unwrap();
        assert!(matches!(
            document.add_flowed_spans(0, &[first, second], style),
            Err(OfdError::Invalid(_))
        ));
        assert_eq!(document.to_bytes().unwrap(), before);
    }

    #[test]
    fn flowed_spans_keep_clusters_across_span_boundaries() {
        let mut prepared = std::array::from_fn::<_, 2, _>(|_| PreparedFlowSpan {
            font_id: "1".into(),
            font_size: 4.0,
            language: None,
            fill_color: None,
            fill: true,
            stroke: false,
            stroke_color: None,
            stroke_width: None,
            bold: false,
            weight: None,
            italic: false,
            letter_spacing: 0.0,
            underline: false,
            underline_offset: 1.2,
            underline_width: 0.0,
            keep_together: false,
            metrics: FlowFontMetrics {
                advances: HashMap::new(),
                kerning: HashMap::new(),
            },
        });
        let paragraph = vec![
            FlowGlyph {
                ch: 'X',
                span_index: 0,
                width: 0.3,
            },
            FlowGlyph {
                ch: 'A',
                span_index: 0,
                width: 0.5,
            },
            FlowGlyph {
                ch: '\u{301}',
                span_index: 1,
                width: 0.5,
            },
            FlowGlyph {
                ch: 'B',
                span_index: 1,
                width: 0.4,
            },
        ];
        let lines =
            wrap_styled_flow_lines(std::slice::from_ref(&paragraph), 1.0, 0.0, &prepared, false)
                .unwrap();
        let text = lines
            .iter()
            .map(|line| line.glyphs.iter().map(|glyph| glyph.ch).collect::<String>())
            .collect::<Vec<_>>();
        assert_eq!(text, ["X", "A\u{301}", "B"]);

        prepared[1].keep_together = true;
        let lines = wrap_styled_flow_lines(&[paragraph], 1.5, 0.0, &prepared, false).unwrap();
        let text = lines
            .iter()
            .map(|line| line.glyphs.iter().map(|glyph| glyph.ch).collect::<String>())
            .collect::<Vec<_>>();
        assert_eq!(text, ["X", "A\u{301}B"]);
        assert!((lines[1].width - 1.4).abs() < 1e-9);

        prepared[1].keep_together = false;
        let word = "hello world"
            .chars()
            .enumerate()
            .map(|(index, ch)| FlowGlyph {
                ch,
                span_index: usize::from(index >= 6),
                width: 1.0,
            })
            .collect::<Vec<_>>();
        let lines = wrap_styled_flow_lines(&[word], 8.0, 0.0, &prepared, false).unwrap();
        let text = lines
            .iter()
            .map(|line| line.glyphs.iter().map(|glyph| glyph.ch).collect::<String>())
            .collect::<Vec<_>>();
        assert_eq!(text, ["hello ", "world"]);
    }

