    #[test]
    fn ses_verification_rejects_unsupported_and_malformed_inputs() {
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-reader/src/test/resources/SESV4SignDoc.ofd");
        let original = OfdDocument::open(fixture).unwrap();
        let signature = &original.signatures().unwrap()[0];
        let path = &signature.signed_value_path;
        let data = original.signed_value_data(0).unwrap();
        let parsed = parse_ses_signed_value(data).unwrap();
        let base = data.as_ptr() as usize;
        let cert_offset = parsed.certificate.as_ptr() as usize - base;
        let signature_offset = parsed.signature.as_ptr() as usize - base;
        let tbs_offset = parsed.tbs_der.as_ptr() as usize - base;

        let mut unsupported_version = original.clone();
        let mut changed = data.to_vec();
        changed[tbs_offset + 6] = 3;
        unsupported_version.set_entry(path, changed).unwrap();
        assert!(matches!(
            unsupported_version.check_ses_signature_value(0),
            Err(OfdError::Invalid(message)) if message.contains("unsupported SES version")
        ));

        let mut unsupported_algorithm = original.clone();
        let mut changed = data.to_vec();
        let oid = [0x06, 0x08, 0x2a, 0x81, 0x1c, 0xcf, 0x55, 0x01, 0x83, 0x75];
        let oid_offset = changed
            .windows(oid.len())
            .rposition(|window| window == oid)
            .unwrap();
        changed[oid_offset + oid.len() - 1] ^= 1;
        unsupported_algorithm.set_entry(path, changed).unwrap();
        assert!(matches!(
            unsupported_algorithm.check_ses_signature_value(0),
            Err(OfdError::Invalid(message)) if message.contains("unsupported SES signature algorithm")
        ));

        let mut invalid_certificate = original.clone();
        let mut changed = data.to_vec();
        changed[cert_offset] = 0x31;
        invalid_certificate.set_entry(path, changed).unwrap();
        assert!(matches!(
            invalid_certificate.check_ses_signature_value(0),
            Err(OfdError::Invalid(message)) if message.contains("invalid SES signer certificate")
        ));

        let mut invalid_signature = original.clone();
        let mut changed = data.to_vec();
        changed[signature_offset] = 0x31;
        invalid_signature.set_entry(path, changed).unwrap();
        assert!(matches!(
            invalid_signature.check_ses_signature_value(0),
            Err(OfdError::Invalid(message)) if message.contains("not valid DER")
        ));
    }

