    #[test]
    fn rejects_archive_traversal() {
        assert!(normalize_path("../../secret", false).is_err());
        assert!(normalize_path("/secret", false).is_err());
        assert!(normalize_path("C:\\secret", false).is_err());
    }

    #[test]
    fn rejects_unsafe_and_duplicate_normalized_zip_entries() {
        let archive = |paths: &[&str]| {
            let mut writer = ZipWriter::new(Cursor::new(Vec::new()));
            for path in paths {
                writer
                    .start_file(*path, zip::write::SimpleFileOptions::default())
                    .unwrap();
                writer.write_all(b"entry").unwrap();
            }
            writer.finish().unwrap().into_inner()
        };
        let traversal = archive(&["../OFD.xml"]);
        assert!(matches!(
            OfdDocument::from_bytes(&traversal),
            Err(OfdError::InvalidPath(_))
        ));
        let duplicate = archive(&["Doc_0/Document.xml", "Doc_0/Pages/../Document.xml"]);
        assert!(matches!(
            OfdDocument::from_bytes(&duplicate),
            Err(OfdError::Invalid(message)) if message.contains("duplicate entry Doc_0/Document.xml")
        ));
    }

    #[test]
    fn reads_utf16_xml_without_changing_original_entry_bytes() {
        fn encoded(source: &[u8], little_endian: bool, bom: bool) -> Vec<u8> {
            let source = std::str::from_utf8(source)
                .unwrap()
                .replace("encoding=\"UTF-8\"", "encoding=\"UTF-16\"");
            let mut bytes = Vec::new();
            if bom {
                bytes.extend(if little_endian {
                    [0xff, 0xfe]
                } else {
                    [0xfe, 0xff]
                });
            }
            for unit in source.encode_utf16() {
                bytes.extend(if little_endian {
                    unit.to_le_bytes()
                } else {
                    unit.to_be_bytes()
                });
            }
            bytes
        }

        let mut document = OfdDocument::new();
        document.add_text_page("中文 OFD", 40.0, 30.0).unwrap();
        let attachment = encoded(
            b"<?xml version=\"1.0\" encoding=\"UTF-8\"?><Payload/>",
            true,
            true,
        );
        document.add_attachment("payload.xml", &attachment).unwrap();
        let page_path = document.pages().unwrap()[0].path.clone();
        for (path, little_endian, bom) in [
            ("OFD.xml", true, true),
            ("Doc_0/Document.xml", false, false),
            (page_path.as_str(), true, false),
            ("Doc_0/PublicRes.xml", false, true),
        ] {
            let raw = encoded(document.entry(path).unwrap().unwrap(), little_endian, bom);
            document.set_entry(path, raw).unwrap();
        }
        let original = document.entries.clone();
        let mut reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), vec!["中文 OFD"]);
        assert_eq!(reopened.attachment_data(0).unwrap(), attachment);
        assert!(reopened.archive_violations().is_ok());
        assert_eq!(
            reopened.prepare_archive().unwrap().page_text(0).unwrap(),
            vec!["中文 OFD"]
        );
        let mut archived_source = reopened.clone();
        archived_source
            .set_attachment_metadata(
                0,
                AttachmentMetadata {
                    format: Some("BIN".into()),
                    ..AttachmentMetadata::default()
                },
            )
            .unwrap();
        let archived = archived_source.prepare_archive().unwrap();
        let digest = Sha256::digest(&attachment)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        assert!(std::str::from_utf8(archived.attachment_data(0).unwrap())
            .unwrap()
            .contains(&digest));
        let mut versioned = reopened.clone();
        versioned.add_version_snapshot(0, "utf16", None).unwrap();
        let snapshot = versioned.extract_version_snapshot(0).unwrap();
        assert_eq!(snapshot.page_text(0).unwrap(), vec!["中文 OFD"]);
        assert_eq!(
            snapshot.entry(&page_path).unwrap().unwrap(),
            original[&page_path]
        );
        assert_eq!(snapshot.attachment_data(0).unwrap(), attachment);
        assert_eq!(
            reopened.package_info().unwrap().version.as_deref(),
            Some("1.2")
        );
        for (path, raw) in &original {
            assert_eq!(reopened.entry(path).unwrap().unwrap(), raw);
        }
        let encrypted = reopened
            .encrypt_with_passwords(&[PasswordRecipient {
                username: "reader".into(),
                password: "secret".into(),
                user_type: None,
            }])
            .unwrap();
        let decrypted = encrypted.decrypt_with_password("secret", None).unwrap();
        assert_eq!(decrypted.page_text(0).unwrap(), vec!["中文 OFD"]);
        assert_eq!(
            decrypted.entry(&page_path).unwrap().unwrap(),
            original[&page_path]
        );
        reopened.set_package_header("2.0", "OFD").unwrap();
        let updated = reopened.entry("OFD.xml").unwrap().unwrap();
        assert!(updated.starts_with(b"<?xml version=\"1.0\" encoding=\"UTF-8\""));
        assert_eq!(
            reopened.entry(&page_path).unwrap().unwrap(),
            original[&page_path]
        );
        let round_trip = OfdDocument::from_bytes(&reopened.to_bytes().unwrap()).unwrap();
        assert_eq!(round_trip.page_text(0).unwrap(), vec!["中文 OFD"]);
    }

    #[test]
    fn rejects_invalid_utf16_xml_without_modifying_document() {
        let mut document = OfdDocument::new();
        let original = document.entry("OFD.xml").unwrap().unwrap().to_vec();
        for invalid in [vec![0xff, 0xfe, b'<'], vec![0xff, 0xfe, 0x00, 0xd8]] {
            assert!(document.set_entry("OFD.xml", invalid).is_err());
            assert_eq!(document.entry("OFD.xml").unwrap().unwrap(), original);
        }
    }

    #[test]
    fn detects_bomless_utf16_xml_after_leading_whitespace() {
        for little_endian in [true, false] {
            let mut bytes = Vec::new();
            for unit in " \n<Root/>".encode_utf16() {
                bytes.extend(if little_endian {
                    unit.to_le_bytes()
                } else {
                    unit.to_be_bytes()
                });
            }
            let view = utf16_xml_view("Doc_0/Extension", &bytes).unwrap().unwrap();
            assert_eq!(
                parse_xml("Doc_0/Extension", &view)
                    .unwrap()
                    .root_element()
                    .tag_name()
                    .name(),
                "Root"
            );
        }
        assert!(utf16_xml_view("payload.dat", &[0xff, 0xfe, 0x00, 0xd8])
            .unwrap()
            .is_none());
    }

    #[test]
    fn signature_references_hash_original_utf16_xml_bytes() {
        let mut document = OfdDocument::new();
        document.add_text_page("签名页", 40.0, 30.0).unwrap();
        let page_path = document.pages().unwrap()[0].path.clone();
        let source = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
        let mut utf16 = vec![0xff, 0xfe];
        for unit in source.encode_utf16() {
            utf16.extend(unit.to_le_bytes());
        }
        document.set_entry(&page_path, utf16.clone()).unwrap();
        document
            .add_digital_signature(&[1; 32], "2024-01-01 00:00:00")
            .unwrap();
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.entry(&page_path).unwrap().unwrap(), utf16);
        assert_eq!(reopened.page_text(0).unwrap(), vec!["签名页"]);
        assert!(reopened
            .check_signature_references(0)
            .unwrap()
            .iter()
            .all(|reference| reference.valid));
    }

