    #[test]
    fn rejects_malformed_uppercase_xml_in_structured_updates() {
        let mut document = OfdDocument::new();
        let before = document.to_bytes().unwrap();
        let error = document
            .apply_entries(vec![("Doc_0/Broken.XML".into(), b"<Broken>".to_vec())])
            .unwrap_err();
        assert!(matches!(error, OfdError::Xml { .. }));
        assert_eq!(document.to_bytes().unwrap(), before);

        document
            .set_entry("Doc_0/Broken.XML", b"<Broken>".to_vec())
            .unwrap();
        assert_eq!(
            document.entry("Doc_0/Broken.XML").unwrap(),
            Some(b"<Broken>".as_slice())
        );
    }

