    #[test]
    fn append_rejects_broken_existing_document_without_mutation() {
        let source = OfdDocument::new();
        let bytes = source.to_bytes().unwrap();
        let original = String::from_utf8(
            source
                .entry("Doc_0/Document.xml")
                .unwrap()
                .unwrap()
                .to_vec(),
        )
        .unwrap();
        for damaged in [
            original.replace(
                "<ofd:MaxUnitID>1</ofd:MaxUnitID>",
                "<ofd:MaxUnitID>bad</ofd:MaxUnitID>",
            ),
            original.replace("<ofd:MaxUnitID>1</ofd:MaxUnitID>", ""),
            original.replace("<ofd:PublicRes>PublicRes.xml</ofd:PublicRes>", ""),
            original.replace("<ofd:Pages></ofd:Pages>", ""),
        ] {
            let mut document = OfdDocument::from_bytes(&bytes).unwrap();
            document
                .set_entry("Doc_0/Document.xml", damaged.into_bytes())
                .unwrap();
            let before = document
                .entry("Doc_0/Document.xml")
                .unwrap()
                .unwrap()
                .to_vec();
            assert!(document.append_text_page(0, "new", 210.0, 297.0).is_err());
            assert_eq!(
                document.entry("Doc_0/Document.xml").unwrap().unwrap(),
                before
            );
        }
        let mut document = OfdDocument::from_bytes(&bytes).unwrap();
        document
            .set_entry("Doc_0/Pages/RustPage_2/Content.xml", b"<custom/>".to_vec())
            .unwrap();
        assert!(document.append_text_page(0, "new", 210.0, 297.0).is_err());
        assert!(document.append_text_page(0, "new", 0.0, 297.0).is_err());
        let mut document = OfdDocument::from_bytes(&bytes).unwrap();
        assert!(document.append_text_page(0, "page", 0.0, 297.0).is_err());
    }

    #[test]
    fn page_area_falls_back_to_highest_template_then_a4() {
        let mut document = OfdDocument::new();
        document.add_text_page("page", 210.0, 297.0).unwrap();
        let page_path = "Doc_0/Pages/Page_0/Content.xml";
        let page = String::from_utf8(document.entry(page_path).unwrap().unwrap().to_vec()).unwrap();
        let page = page
            .replace("<ofd:Area><ofd:PhysicalBox>0 0 210 297</ofd:PhysicalBox></ofd:Area>", "")
            .replace("<ofd:Content>", "<ofd:Template TemplateID=\"8\" ZOrder=\"Background\"/><ofd:Template TemplateID=\"9\" ZOrder=\"Foreground\"/><ofd:Content>");
        document.set_entry(page_path, page.into_bytes()).unwrap();
        let root = "Doc_0/Document.xml";
        let doc = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
        let doc = doc.replace(
            "</ofd:CommonData>",
            "<ofd:TemplatePage ID=\"8\" BaseLoc=\"Tpls/Bg.xml\"/><ofd:TemplatePage ID=\"9\" BaseLoc=\"Tpls/Fg.xml\"/></ofd:CommonData>",
        );
        document.set_entry(root, doc.into_bytes()).unwrap();
        for (name, width) in [("Bg", 100), ("Fg", 180)] {
            document
                .set_entry(
                    &format!("Doc_0/Tpls/{name}.xml"),
                    format!("<Page><Area><PhysicalBox>0 0 {width} 250</PhysicalBox><ApplicationBox>5 5 {} 240</ApplicationBox><ContentBox>10 10 {} 230</ContentBox></Area></Page>", width - 10, width - 20)
                        .into_bytes(),
                )
                .unwrap();
        }
        assert_eq!(
            document.pages().unwrap()[0].physical_box,
            Some([0.0, 0.0, 180.0, 250.0])
        );
        assert_eq!(
            document.pages().unwrap()[0].application_box,
            Some([5.0, 5.0, 170.0, 240.0])
        );
        assert_eq!(
            document.pages().unwrap()[0].content_box,
            Some([10.0, 10.0, 160.0, 230.0])
        );
        let foreground_path = "Doc_0/Tpls/Fg.xml";
        let foreground =
            String::from_utf8(document.entry(foreground_path).unwrap().unwrap().to_vec()).unwrap();
        document
            .set_entry(
                foreground_path,
                foreground
                    .replace(
                        "<ContentBox>10 10 160 230</ContentBox>",
                        "<ContentBox>bad</ContentBox>",
                    )
                    .into_bytes(),
            )
            .unwrap();
        assert!(matches!(document.pages(), Err(OfdError::Invalid(_))));
        document
            .set_entry(foreground_path, foreground.as_bytes().to_vec())
            .unwrap();
        document
            .set_entry(
                foreground_path,
                foreground
                    .replace(
                        "</Area>",
                        "</Area><Area><PhysicalBox>0 0 100 100</PhysicalBox></Area>",
                    )
                    .into_bytes(),
            )
            .unwrap();
        assert!(matches!(document.pages(), Err(OfdError::Invalid(_))));
        document
            .set_entry(foreground_path, foreground.as_bytes().to_vec())
            .unwrap();
        document
            .set_entry(
                foreground_path,
                foreground
                    .replace("<PhysicalBox>0 0 180 250</PhysicalBox>", "")
                    .into_bytes(),
            )
            .unwrap();
        assert_eq!(
            document.pages().unwrap()[0].physical_box,
            Some([5.0, 5.0, 170.0, 240.0])
        );
        let page = String::from_utf8(document.entry(page_path).unwrap().unwrap().to_vec()).unwrap();
        document.set_entry(page_path, page.replace("<ofd:Template TemplateID=\"8\" ZOrder=\"Background\"/><ofd:Template TemplateID=\"9\" ZOrder=\"Foreground\"/>", "").into_bytes()).unwrap();
        let doc = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
        document
            .set_entry(
                root,
                doc.replace(
                    "<ofd:PageArea><ofd:PhysicalBox>0 0 210 297</ofd:PhysicalBox></ofd:PageArea>",
                    "",
                )
                .into_bytes(),
            )
            .unwrap();
        assert_eq!(
            document.pages().unwrap()[0].physical_box,
            Some([0.0, 0.0, 210.0, 297.0])
        );
        assert!(document.pages().unwrap()[0].application_box.is_none());
        assert_eq!(
            document.pages().unwrap()[0].bleed_box,
            Some([0.0, 0.0, 210.0, 297.0])
        );
        let page = String::from_utf8(document.entry(page_path).unwrap().unwrap().to_vec()).unwrap();
        let page = page.replace(
            "<ofd:Content>",
            "<ofd:Area><ofd:ApplicationBox>1 2 30 40</ofd:ApplicationBox></ofd:Area><ofd:Content>",
        );
        document.set_entry(page_path, page.into_bytes()).unwrap();
        assert_eq!(
            document.pages().unwrap()[0].physical_box,
            Some([1.0, 2.0, 30.0, 40.0])
        );
        let page = String::from_utf8(document.entry(page_path).unwrap().unwrap().to_vec()).unwrap();
        document
            .set_entry(
                page_path,
                page.replace(
                    "<ofd:ApplicationBox>1 2 30 40</ofd:ApplicationBox>",
                    "<ofd:ContentBox>3 4 20 25</ofd:ContentBox>",
                )
                .into_bytes(),
            )
            .unwrap();
        assert_eq!(
            document.pages().unwrap()[0].physical_box,
            Some([3.0, 4.0, 20.0, 25.0])
        );
    }

    #[test]
