    #[test]
    fn document_permissions_round_trip_and_preserve_other_xml() {
        let mut document = OfdDocument::new();
        assert_eq!(
            document.document_permissions(0).unwrap(),
            DocumentPermissions::default()
        );
        assert!(document.document_permissions(1).is_err());
        let permissions = DocumentPermissions {
            edit: false,
            annot: false,
            export: true,
            signature: false,
            watermark: true,
            print_screen: false,
            print: PrintPermission {
                printable: true,
                copies: 2,
            },
            valid_period: Some(ValidPeriod {
                start_date: Some("2024-02-29T09:00:00".into()),
                end_date: Some("2025-03-01T17:30:00".into()),
            }),
        };
        document.set_document_permissions(0, &permissions).unwrap();
        assert_eq!(document.document_permissions(0).unwrap(), permissions);
        let path = "Doc_0/Document.xml";
        let xml = String::from_utf8(document.entry(path).unwrap().unwrap().to_vec()).unwrap();
        document
            .set_entry(
                path,
                xml.replace(
                    "</ofd:Permissions>",
                    "<!--keep--><x:Extension xmlns:x=\"urn:example\"/> </ofd:Permissions>",
                )
                .into_bytes(),
            )
            .unwrap();
        let mut updated = permissions.clone();
        updated.print.copies = 0;
        updated.valid_period = None;
        document.set_document_permissions(0, &updated).unwrap();
        let xml = String::from_utf8(document.entry(path).unwrap().unwrap().to_vec()).unwrap();
        assert!(xml.contains("<!--keep-->"));
        assert!(xml.contains("<x:Extension xmlns:x=\"urn:example\"/>"));
        assert!(xml.contains("<ofd:Pages>"));
        assert!(!xml.contains("ValidPeriod"));
        assert_eq!(document.document_permissions(0).unwrap(), updated);
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.document_permissions(0).unwrap(), updated);
    }

    #[test]
    fn permissions_and_preferences_ignore_extension_namespace_lookalikes() {
        let mut document = OfdDocument::new();
        let permissions = DocumentPermissions {
            edit: false,
            print: PrintPermission {
                printable: true,
                copies: 2,
            },
            ..DocumentPermissions::default()
        };
        let preferences = ViewPreferences {
            page_mode: "UseOutlines".into(),
            ..ViewPreferences::default()
        };
        document.set_document_permissions(0, &permissions).unwrap();
        document.set_view_preferences(0, &preferences).unwrap();
        let path = "Doc_0/Document.xml";
        let xml = String::from_utf8(document.entry(path).unwrap().unwrap().to_vec()).unwrap();
        let xml = xml
            .replace(
                "<ofd:Permissions>",
                "<x:Permissions xmlns:x=\"urn:example:extension\"><x:Edit>true</x:Edit></x:Permissions><ofd:Permissions><x:Edit xmlns:x=\"urn:example:extension\">true</x:Edit><x:Print xmlns:x=\"urn:example:extension\" Printable=\"false\" Copies=\"999\"/><x:ValidPeriod xmlns:x=\"urn:example:extension\" StartDate=\"invalid\"/>",
            )
            .replace(
                "<ofd:VPreferences>",
                "<x:VPreferences xmlns:x=\"urn:example:extension\"><x:PageMode>FullScreen</x:PageMode></x:VPreferences><ofd:VPreferences><x:PageMode xmlns:x=\"urn:example:extension\">FullScreen</x:PageMode><x:Zoom xmlns:x=\"urn:example:extension\">invalid</x:Zoom>",
            );
        document.set_entry(path, xml.into_bytes()).unwrap();

        assert_eq!(document.document_permissions(0).unwrap(), permissions);
        assert_eq!(document.view_preferences(0).unwrap(), preferences);

        let updated_permissions = DocumentPermissions {
            edit: true,
            print: PrintPermission {
                printable: true,
                copies: 3,
            },
            ..permissions
        };
        let updated_preferences = ViewPreferences {
            page_mode: "UseThumbs".into(),
            ..preferences
        };
        document
            .set_document_permissions(0, &updated_permissions)
            .unwrap();
        document
            .set_view_preferences(0, &updated_preferences)
            .unwrap();
        let xml = String::from_utf8(document.entry(path).unwrap().unwrap().to_vec()).unwrap();
        assert!(xml.contains("<x:Edit xmlns:x=\"urn:example:extension\">true</x:Edit>"));
        assert!(xml.contains(
            "<x:Print xmlns:x=\"urn:example:extension\" Printable=\"false\" Copies=\"999\"/>"
        ));
        assert!(
            xml.contains("<x:PageMode xmlns:x=\"urn:example:extension\">FullScreen</x:PageMode>")
        );
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(
            reopened.document_permissions(0).unwrap(),
            updated_permissions
        );
        assert_eq!(reopened.view_preferences(0).unwrap(), updated_preferences);
    }

    #[test]
    fn document_permissions_validate_dates_and_reject_ambiguous_xml() {
        let mut document = OfdDocument::new();
        let before = document.to_bytes().unwrap();
        for (start, end) in [
            ("2025-02-29T00:00:00", "2025-03-01T00:00:00"),
            ("2025-03-02T00:00:00", "2025-03-01T00:00:00"),
            ("2025-01-01 00:00:00", "2025-03-01T00:00:00"),
        ] {
            let permissions = DocumentPermissions {
                valid_period: Some(ValidPeriod {
                    start_date: Some(start.into()),
                    end_date: Some(end.into()),
                }),
                ..DocumentPermissions::default()
            };
            assert!(document.set_document_permissions(0, &permissions).is_err());
        }
        assert_eq!(document.to_bytes().unwrap(), before);
        let path = "Doc_0/Document.xml";
        let xml = String::from_utf8(document.entry(path).unwrap().unwrap().to_vec()).unwrap();
        document
            .set_entry(
                path,
                xml.replace(
                    "<ofd:Pages>",
                    "<ofd:Permissions><ofd:Edit>true</ofd:Edit><ofd:Edit>false</ofd:Edit></ofd:Permissions><ofd:Pages>",
                )
                .into_bytes(),
            )
            .unwrap();
        assert!(document.document_permissions(0).is_err());
        assert!(document
            .set_document_permissions(0, &DocumentPermissions::default())
            .is_err());
    }

    #[test]
